import fs, { type FileHandle } from 'node:fs/promises'
import type { Stats } from 'node:fs'
import {
  CREATE_FLAGS, NOT_FOUND, PathError, RequestError, at, isMarkdownName, isSource, openRegularFile, temporaryFileName, validateEntryPath,
  withParentDirectory, type FixtureRoot, type Source, type Target,
} from './files.ts'

/**
 * Bounded file and folder operations. Every step is descriptor-relative (see files.ts); nothing here
 * re-resolves a validated pathname. All operations run through the same serial queue as content saves.
 *
 * Collision policy: a filesystem probe (lstat of the destination name inside its open parent) refuses
 * anything that exists, including dangling symlinks; file creation stages with O_EXCL then links,
 * folders use mkdir, file renames use
 * link + unlink (link fails on an existing name), folder renames use rename after the probe.
 */
export type MutationRequest =
  | { op: 'create-file'; source: Source; path: string; content: string }
  | { op: 'create-folder'; source: Source; path: string }
  | { op: 'rename'; source: Source; path: string; destinationPath: string }
  | { op: 'move'; source: Source; path: string; destinationPath: string }
  | { op: 'delete'; source: Source; path: string }
  | { op: 'copy'; source: Source; path: string; destinationSource: Source; destinationPath: string }

export type MutationResult = { status: 200 | 201; body: { op: string; source: Source; path: string; destinationSource?: Source; destinationPath?: string } }

const DESTINATION_EXISTS = new RequestError(409, 'DESTINATION_EXISTS', 'Something already exists at that destination. Choose another name.')
const FOLDER_NOT_EMPTY = new RequestError(409, 'FOLDER_NOT_EMPTY', 'The folder is not empty. Only empty folders can be renamed, moved or deleted.')
const NO_CHANGE = new RequestError(409, 'NO_CHANGE', 'The destination is the same as the current path.')

function field(body: Record<string, unknown>, name: string): string {
  const value = body[name]
  if (typeof value !== 'string') throw new RequestError(400, 'INVALID_BODY', `The ${name} field must be a string.`)
  return value
}

/** Parses the discriminated request body. Source names are checked here; paths are validated by the operation. */
export function parseMutationBody(body: unknown): MutationRequest {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    throw new RequestError(400, 'INVALID_BODY', 'The request body must be a JSON object with an op, source and path.')
  }
  const record = body as Record<string, unknown>
  const source = record.source
  if (!isSource(source)) throw new RequestError(400, 'INVALID_SOURCE', 'The source must be Pi or Claude.')
  const path = field(record, 'path')
  switch (record.op) {
    case 'create-file': {
      const content = record.content === undefined ? '' : record.content
      if (typeof content !== 'string') throw new RequestError(400, 'INVALID_CONTENT', 'The content must be a string.')
      return { op: 'create-file', source, path, content }
    }
    case 'create-folder':
      return { op: 'create-folder', source, path }
    case 'delete':
      return { op: 'delete', source, path }
    case 'rename':
    case 'move': {
      if (record.destinationSource !== undefined && record.destinationSource !== source) {
        throw new RequestError(400, 'INVALID_SOURCE', `A ${record.op} stays within the same source.`)
      }
      return { op: record.op, source, path, destinationPath: field(record, 'destinationPath') }
    }
    case 'copy': {
      const destinationSource = record.destinationSource
      if (!isSource(destinationSource)) throw new RequestError(400, 'INVALID_SOURCE', 'The destination source must be Pi or Claude.')
      if (destinationSource === source) throw new RequestError(400, 'INVALID_SOURCE', 'Copy targets the other source only.')
      return { op: 'copy', source, path, destinationSource, destinationPath: field(record, 'destinationPath') }
    }
    default:
      throw new RequestError(400, 'INVALID_OP', 'The op must be create-file, create-folder, rename, move, delete or copy.')
  }
}

function sameComponents(a: string[], b: string[]): boolean {
  return a.length === b.length && a.every((component, index) => component === b[index])
}

/** lstat inside the open parent: reports whatever occupies the name, including a dangling symlink. */
async function probe(parent: FileHandle, name: string): Promise<Stats | null> {
  try {
    return await fs.lstat(at(parent, name))
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null
    throw error
  }
}

async function assertAbsent(parent: FileHandle, name: string): Promise<void> {
  if (await probe(parent, name)) throw DESTINATION_EXISTS
}

/** Resolves an existing mutation target: a regular Markdown file or a directory, never a symlink or other type. */
async function existingTarget(parent: FileHandle, name: string): Promise<'file' | 'folder'> {
  const stats = await probe(parent, name)
  if (!stats || stats.isSymbolicLink()) throw new PathError(404, NOT_FOUND)
  if (stats.isDirectory()) return 'folder'
  if (stats.isFile() && isMarkdownName(name)) return 'file'
  throw new PathError(404, NOT_FOUND)
}

async function assertEmptyFolder(parent: FileHandle, name: string): Promise<void> {
  // Includes hidden and non-Markdown entries the listing never shows.
  if ((await fs.readdir(at(parent, name))).length > 0) throw FOLDER_NOT_EMPTY
}

function conflictFromErrno(error: unknown): never {
  const code = (error as NodeJS.ErrnoException)?.code
  if (code === 'EEXIST') throw DESTINATION_EXISTS
  if (code === 'ENOTEMPTY') throw FOLDER_NOT_EMPTY
  throw error
}

/** Finish bytes and permissions privately, then publish with an exclusive hard link. A failed
 * stage never owns the destination name, so cleanup cannot delete an external replacement there. */
async function publishFile(parent: FileHandle, name: string, bytes: Buffer, mode?: number): Promise<void> {
  await assertAbsent(parent, name)
  const temporary = at(parent, temporaryFileName())
  const file = await fs.open(temporary, CREATE_FLAGS, 0o644)
  try {
    if (mode !== undefined) await file.chmod(mode)
    await file.writeFile(bytes)
    await file.close()
    await fs.link(temporary, at(parent, name)).catch(conflictFromErrno)
  } finally {
    await file.close().catch(() => undefined)
    // Publication commits at link(): cleanup must neither turn success into failure nor
    // mask an earlier write/collision error. A leaked non-Markdown stage is logged only.
    await fs.unlink(temporary).catch(error => {
      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
        console.warn('Could not remove mutation staging file:', error)
      }
    })
  }
}

async function createFile(root: FixtureRoot, target: Target, content: string): Promise<void> {
  await withParentDirectory(root, target.source, target.components, (parent, name) =>
    publishFile(parent, name, Buffer.from(content, 'utf8')))
}

async function createFolder(root: FixtureRoot, target: Target): Promise<void> {
  await withParentDirectory(root, target.source, target.components, async (parent, name) => {
    await assertAbsent(parent, name)
    await fs.mkdir(at(parent, name)).catch(conflictFromErrno)
  })
}

async function deleteEntry(root: FixtureRoot, target: Target): Promise<void> {
  await withParentDirectory(root, target.source, target.components, async (parent, name) => {
    const kind = await existingTarget(parent, name)
    if (kind === 'file') {
      await fs.unlink(at(parent, name))
    } else {
      await assertEmptyFolder(parent, name)
      await fs.rmdir(at(parent, name)).catch(conflictFromErrno)
    }
  })
}

/** Rename and move share one implementation; the caller has already checked the parent relationship. */
async function relocate(root: FixtureRoot, from: Target, to: Target): Promise<void> {
  if (sameComponents(from.components, to.components)) throw NO_CHANGE
  const fromParent = from.components.slice(0, -1)
  if (to.components.length > from.components.length && sameComponents(from.components, to.components.slice(0, from.components.length))) {
    throw new PathError(400, 'A folder cannot be moved into itself.')
  }
  await withParentDirectory(root, from.source, from.components, async (sourceParent, sourceName) => {
    const kind = await existingTarget(sourceParent, sourceName)
    const destinationName = to.components[to.components.length - 1]
    if (kind === 'file' && !isMarkdownName(destinationName)) throw new PathError(400, 'The file name must end in .md.')
    if (kind === 'folder' && isMarkdownName(destinationName)) throw new PathError(400, 'A folder name must not end in .md.')
    if (kind === 'folder') await assertEmptyFolder(sourceParent, sourceName)
    const run = async (destinationParent: FileHandle) => {
      await assertAbsent(destinationParent, destinationName)
      if (kind === 'file') {
        // link() refuses an existing destination atomically; the old name is removed only once the new one exists.
        await fs.link(at(sourceParent, sourceName), at(destinationParent, destinationName)).catch(conflictFromErrno)
        try {
          await fs.unlink(at(sourceParent, sourceName))
        } catch (error) {
          await fs.unlink(at(destinationParent, destinationName)).catch(() => undefined)
          throw error
        }
      } else {
        await fs.rename(at(sourceParent, sourceName), at(destinationParent, destinationName)).catch(conflictFromErrno)
      }
    }
    if (sameComponents(fromParent, to.components.slice(0, -1))) await run(sourceParent)
    else await withParentDirectory(root, to.source, to.components, destinationParent => run(destinationParent))
  })
}

async function copyFile(root: FixtureRoot, from: Target, to: Target): Promise<void> {
  await withParentDirectory(root, from.source, from.components, async (sourceParent, sourceName, track) => {
    const source = await openRegularFile(sourceParent, sourceName)
    track(source)
    const stats = await source.stat()
    const bytes = await source.readFile()
    await withParentDirectory(root, to.source, to.components, async (destinationParent, destinationName) => {
      await publishFile(destinationParent, destinationName, bytes, stats.mode & 0o7777)
    })
  })
}

/** Validates everything lexically, then runs the operation inside the shared serial queue. */
export async function performMutation(root: FixtureRoot, request: MutationRequest): Promise<MutationResult> {
  const { op, source, path } = request
  return root.mutations.run(async (): Promise<MutationResult> => {
    switch (op) {
      case 'create-file': {
        const target = validateEntryPath(source, path, 'file')
        await createFile(root, target, request.content)
        return { status: 201, body: { op, source, path: target.components.join('/') } }
      }
      case 'create-folder': {
        const target = validateEntryPath(source, path, 'folder')
        await createFolder(root, target)
        return { status: 201, body: { op, source, path: target.components.join('/') } }
      }
      case 'delete': {
        const target = validateEntryPath(source, path, 'any')
        await deleteEntry(root, target)
        return { status: 200, body: { op, source, path: target.components.join('/') } }
      }
      case 'rename':
      case 'move': {
        const from = validateEntryPath(source, path, 'any')
        const to = validateEntryPath(source, request.destinationPath, 'any')
        if (op === 'rename' && !sameComponents(from.components.slice(0, -1), to.components.slice(0, -1))) {
          throw new PathError(400, 'A rename keeps the same parent folder. Use move to change folders.')
        }
        await relocate(root, from, to)
        return { status: 200, body: { op, source, path: from.components.join('/'), destinationSource: source, destinationPath: to.components.join('/') } }
      }
      case 'copy': {
        const from = validateEntryPath(source, path, 'any')
        if (!isMarkdownName(from.components[from.components.length - 1])) throw new PathError(404, NOT_FOUND)
        const to = validateEntryPath(request.destinationSource, request.destinationPath, 'file')
        await copyFile(root, from, to)
        return { status: 201, body: { op, source, path: from.components.join('/'), destinationSource: request.destinationSource, destinationPath: to.components.join('/') } }
      }
    }
  })
}
/**
 * Pure graph model: builds a containment tree from the flat /api/entries listing and
 * derives what is visible for a given expansion state. No DOM or layout concerns live here.
 */

export type Source = 'Pi' | 'Claude'
export const SOURCES: readonly Source[] = ['Pi', 'Claude']
export type EntryKind = 'directory' | 'file'
export type Entry = { source: Source; path: string; kind: EntryKind }
export type NodeKind = 'source' | 'directory' | 'file'

/** A source root (path '') or a directory inside it. */
export type FolderRef = { source: Source; path: string }

/** A Markdown file identified by source plus nonempty source-relative path. Filename alone is never enough. */
export type FileRef = { source: Source; path: string }

export type GraphNode = {
  id: string
  source: Source
  path: string
  name: string
  kind: NodeKind
  parentId: string | null
  depth: number
}

export type GraphEdge = { id: string; parentId: string; childId: string }

export type TreeIndex = {
  nodes: Map<string, GraphNode>
  /** Immediate children in display order: directories first, then files, each alphabetical. */
  children: Map<string, GraphNode[]>
}

export type ChildCounts = { directories: number; files: number }

export function isSource(value: string): value is Source {
  return value === 'Pi' || value === 'Claude'
}

export function nodeId(source: Source, path: string): string {
  return path ? `${source}/${path}` : source
}

export function refId(ref: FolderRef): string {
  return nodeId(ref.source, ref.path)
}

export function sameRef(a: FolderRef | null, b: FolderRef | null): boolean {
  return a === b || (a !== null && b !== null && a.source === b.source && a.path === b.path)
}

export function sameFileRef(a: FileRef | null, b: FileRef | null): boolean {
  return sameRef(a, b)
}

/** The folder that contains a file: the source root for top-level files. */
export function parentFolderOf(ref: FileRef): FolderRef {
  return { source: ref.source, path: parentPath(ref.path) }
}

function baseName(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1)
}

function parentPath(path: string): string {
  const index = path.lastIndexOf('/')
  return index === -1 ? '' : path.slice(0, index)
}

const collator = new Intl.Collator('en', { numeric: true, sensitivity: 'base' })

function compareNodes(a: GraphNode, b: GraphNode): number {
  if (a.kind !== b.kind) return a.kind === 'directory' ? -1 : 1
  return collator.compare(a.name, b.name) || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0)
}

/** Builds the containment index. Parents are created implicitly if the listing omits them. */
export function buildIndex(entries: readonly Entry[]): TreeIndex {
  const nodes = new Map<string, GraphNode>()
  for (const source of SOURCES) {
    nodes.set(source, { id: source, source, path: '', name: source, kind: 'source', parentId: null, depth: 0 })
  }
  function ensure(source: Source, path: string, kind: NodeKind): GraphNode {
    const id = nodeId(source, path)
    const existing = nodes.get(id)
    if (existing) return existing
    const parent = path.includes('/') ? ensure(source, parentPath(path), 'directory') : nodes.get(source)!
    const node: GraphNode = { id, source, path, name: baseName(path), kind, parentId: parent.id, depth: parent.depth + 1 }
    nodes.set(id, node)
    return node
  }
  for (const entry of entries) {
    if (!isSource(entry.source) || !entry.path || entry.path.split('/').some(segment => segment === '')) continue
    ensure(entry.source, entry.path, entry.kind === 'directory' ? 'directory' : 'file')
  }
  const children = new Map<string, GraphNode[]>()
  for (const node of nodes.values()) {
    if (node.parentId === null) continue
    const siblings = children.get(node.parentId) ?? []
    siblings.push(node)
    children.set(node.parentId, siblings)
  }
  for (const siblings of children.values()) siblings.sort(compareNodes)
  return { nodes, children }
}

export function childrenOf(index: TreeIndex, id: string): GraphNode[] {
  return index.children.get(id) ?? []
}

export function childCounts(index: TreeIndex, id: string): ChildCounts {
  const counts = { directories: 0, files: 0 }
  for (const child of childrenOf(index, id)) {
    if (child.kind === 'file') counts.files += 1
    else counts.directories += 1
  }
  return counts
}

export function describeCounts({ directories, files }: ChildCounts): string {
  if (directories + files === 0) return 'This folder is empty.'
  const parts = [
    `${directories} ${directories === 1 ? 'folder' : 'folders'}`,
    `${files} ${files === 1 ? 'Markdown file' : 'Markdown files'}`,
  ]
  return parts.join(', ')
}

/** Ids of every descendant of `id`, depth-first. */
export function descendantIds(index: TreeIndex, id: string): string[] {
  const result: string[] = []
  const stack = [...childrenOf(index, id)]
  while (stack.length) {
    const node = stack.pop()!
    result.push(node.id)
    stack.push(...childrenOf(index, node.id))
  }
  return result
}

/** Ids of the source and every ancestor directory of `node`, outermost first (excluding the node itself). */
export function ancestorIds(node: GraphNode): string[] {
  const ids: string[] = []
  if (node.kind === 'source') return ids
  ids.push(node.source)
  const segments = node.path.split('/')
  for (let i = 1; i < segments.length; i += 1) ids.push(nodeId(node.source, segments.slice(0, i).join('/')))
  return ids
}

/** Visible nodes in keyboard/DOM order (pre-order: Pi subtree, then Claude subtree), and their containment edges. */
export function visibleGraph(index: TreeIndex, expanded: ReadonlySet<string>): { nodes: GraphNode[]; edges: GraphEdge[] } {
  const nodes: GraphNode[] = []
  const edges: GraphEdge[] = []
  function visit(node: GraphNode) {
    nodes.push(node)
    if (node.kind === 'file' || !expanded.has(node.id)) return
    for (const child of childrenOf(index, node.id)) {
      edges.push({ id: child.id, parentId: node.id, childId: child.id })
      visit(child)
    }
  }
  for (const source of SOURCES) visit(index.nodes.get(source)!)
  return { nodes, edges }
}

/** Collapsing hides every descendant and forgets their expansion state. */
export function collapseNode(index: TreeIndex, expanded: ReadonlySet<string>, id: string): Set<string> {
  const next = new Set(expanded)
  next.delete(id)
  for (const descendant of descendantIds(index, id)) next.delete(descendant)
  return next
}

/** Expands the ancestor chain and the folder itself so it is visible, leaving other branches alone. */
export function revealFolder(index: TreeIndex, expanded: ReadonlySet<string>, ref: FolderRef): Set<string> {
  const node = index.nodes.get(refId(ref))
  if (!node || node.kind === 'file') return new Set(expanded)
  const next = new Set(expanded)
  for (const id of ancestorIds(node)) next.add(id)
  next.add(node.id)
  return next
}

/** Drops ids that no longer exist after a refresh. */
export function pruneIds(index: TreeIndex, ids: ReadonlySet<string>): Set<string> {
  return new Set([...ids].filter(id => index.nodes.has(id)))
}

export function folderExists(index: TreeIndex, ref: FolderRef | null): boolean {
  if (ref === null) return true
  const node = index.nodes.get(refId(ref))
  return node !== undefined && node.kind !== 'file'
}

// ---- URLs ---------------------------------------------------------------------------------------

/** Encodes the selected folder as a pathname, encoding every segment so spaces, #, ? and % survive. */
export function folderToPathname(ref: FolderRef | null): string {
  if (ref === null) return '/'
  const segments = ref.path ? [ref.source, ...ref.path.split('/')] : [ref.source]
  return `/${segments.map(encodeURIComponent).join('/')}`
}

const FILE_ROUTE = 'file'

/** Encodes a document as `/file/<source>/<segment>/…`, encoding every path segment individually. */
export function fileToPathname(ref: FileRef): string {
  return `/${FILE_ROUTE}/${[ref.source, ...ref.path.split('/')].map(encodeURIComponent).join('/')}`
}

export type ParsedLocation =
  | { kind: 'home' }
  | { kind: 'folder'; ref: FolderRef }
  | { kind: 'file'; ref: FileRef }
  | { kind: 'unknown-source'; name: string }
  | { kind: 'malformed' }

/** Decodes each raw segment exactly once; malformed percent-encoding yields null instead of throwing. */
function decodeSegments(raw: string[]): string[] | null {
  try {
    return raw.map(decodeURIComponent)
  } catch {
    return null
  }
}

function parseFilePathname(raw: string[]): ParsedLocation {
  if (raw.length < 2) return { kind: 'malformed' }
  const segments = decodeSegments(raw)
  if (!segments) return { kind: 'malformed' }
  const [source, ...rest] = segments
  if (!isSource(source)) return { kind: 'unknown-source', name: source }
  // Decoded segments must be plain names: no separators, no dot components, nothing empty.
  if (rest.some(segment => segment === '' || segment === '.' || segment === '..' || segment.includes('/'))) {
    return { kind: 'malformed' }
  }
  return { kind: 'file', ref: { source, path: rest.join('/') } }
}

export function parsePathname(pathname: string): ParsedLocation {
  const raw = pathname.split('/').filter(segment => segment !== '')
  if (raw.length === 0) return { kind: 'home' }
  if (raw[0] === FILE_ROUTE) return parseFilePathname(raw.slice(1))
  const segments = decodeSegments(raw)
  if (!segments) return { kind: 'malformed' }
  const [source, ...rest] = segments
  if (!isSource(source)) return { kind: 'unknown-source', name: source }
  return { kind: 'folder', ref: { source, path: rest.join('/') } }
}

/** `ref` is the folder to navigate to (null = Home). A crumb without `ref` is the current document and not a link. */
export type Breadcrumb = { label: string; ref?: FolderRef | null; id: string }

/** Home, then the source, then one crumb per directory segment. */
export function breadcrumbsFor(ref: FolderRef | null): Breadcrumb[] {
  const crumbs: Breadcrumb[] = [{ label: 'Home', ref: null, id: 'home' }]
  if (ref === null) return crumbs
  crumbs.push({ label: ref.source, ref: { source: ref.source, path: '' }, id: ref.source })
  if (!ref.path) return crumbs
  const segments = ref.path.split('/')
  for (let i = 0; i < segments.length; i += 1) {
    const path = segments.slice(0, i + 1).join('/')
    crumbs.push({ label: segments[i], ref: { source: ref.source, path }, id: nodeId(ref.source, path) })
  }
  return crumbs
}

/** The containing folder's trail plus the filename as a non-navigating current item. */
export function breadcrumbsForFile(ref: FileRef): Breadcrumb[] {
  return [...breadcrumbsFor(parentFolderOf(ref)), { label: baseName(ref.path), id: nodeId(ref.source, ref.path) }]
}
import type { FileRef, Source } from '../graph/model.ts'

export type FileDocument = { source: Source; path: string; content: string; hash: string }

export type DocumentErrorKind = 'missing' | 'invalid' | 'failed'

export class DocumentError extends Error {
  readonly kind: DocumentErrorKind
  constructor(kind: DocumentErrorKind, message: string) {
    super(message)
    this.kind = kind
  }
}

/** Fetches one document. The query is built with URLSearchParams so any character in the path survives. */
export async function fetchDocument(ref: FileRef, signal?: AbortSignal): Promise<FileDocument> {
  const query = new URLSearchParams({ source: ref.source, path: ref.path })
  let response: Response
  try {
    response = await fetch(`/api/file?${query.toString()}`, { signal, cache: 'no-store' })
  } catch (error) {
    if (signal?.aborted) throw error
    throw new DocumentError('failed', 'The API could not be reached. Check that it is running.')
  }
  let body: unknown = null
  try { body = await response.json() } catch { /* not JSON */ }
  const record = body && typeof body === 'object' ? (body as Record<string, unknown>) : null
  const serverMessage = typeof record?.error === 'string' ? record.error : null
  if (response.status === 404) throw new DocumentError('missing', serverMessage ?? 'The file was not found.')
  if (response.status === 400) throw new DocumentError('invalid', serverMessage ?? 'The file link is invalid.')
  if (!response.ok) throw new DocumentError('failed', serverMessage ?? `The API responded with status ${response.status}.`)
  if (!record || typeof record.content !== 'string' || typeof record.hash !== 'string' || record.source !== ref.source || record.path !== ref.path) {
    throw new DocumentError('failed', 'The API returned an unexpected response.')
  }
  return { source: ref.source, path: ref.path, content: record.content, hash: record.hash }
}

export type SaveErrorKind = 'failed' | 'conflict' | 'too-large' | 'missing'

export class SaveError extends Error {
  readonly kind: SaveErrorKind
  constructor(kind: SaveErrorKind, message: string) {
    super(message)
    this.kind = kind
  }
}

/** Hash-guarded write. Resolves with the hash of the bytes the server wrote for exactly `content`. */
export async function saveDocument(ref: FileRef, content: string, expectedHash: string): Promise<string> {
  let response: Response
  try {
    response = await fetch('/api/file', {
      method: 'PUT',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ source: ref.source, path: ref.path, content, expectedHash }),
    })
  } catch {
    throw new SaveError('failed', 'The API could not be reached. Check that it is running, then retry.')
  }
  let body: unknown = null
  try { body = await response.json() } catch { /* not JSON */ }
  const record = body && typeof body === 'object' ? (body as Record<string, unknown>) : null
  const serverMessage = typeof record?.error === 'string' ? record.error : null
  if (response.status === 409) throw new SaveError('conflict', serverMessage ?? 'This file changed on disk.')
  if (response.status === 413) throw new SaveError('too-large', serverMessage ?? 'The document is larger than the server accepts.')
  if (response.status === 404) throw new SaveError('missing', serverMessage ?? 'The file no longer exists on disk.')
  if (!response.ok) throw new SaveError('failed', serverMessage ?? `The API responded with status ${response.status}.`)
  if (!record || typeof record.hash !== 'string' || record.source !== ref.source || record.path !== ref.path) {
    throw new SaveError('failed', 'The API returned an unexpected response.')
  }
  return record.hash
}
import type { Source } from '../graph/model.ts'

export type OperationKind = 'create-file' | 'create-folder' | 'rename' | 'move' | 'delete' | 'copy'

export type MutationRequest =
  | { op: 'create-file'; source: Source; path: string; content?: string }
  | { op: 'create-folder'; source: Source; path: string }
  | { op: 'rename'; source: Source; path: string; destinationPath: string }
  | { op: 'move'; source: Source; path: string; destinationPath: string }
  | { op: 'delete'; source: Source; path: string }
  | { op: 'copy'; source: Source; path: string; destinationSource: Source; destinationPath: string }

export type MutationResponse = { op: OperationKind; source: Source; path: string; destinationSource?: Source; destinationPath?: string }

export class OperationError extends Error {
  readonly code: string
  readonly status: number
  constructor(status: number, code: string, message: string) {
    super(message)
    this.status = status
    this.code = code
  }
}

/** Submits one operation. The server is authoritative; its safe message is shown to the user. */
export async function performOperation(request: MutationRequest): Promise<MutationResponse> {
  let response: Response
  try {
    response = await fetch('/api/mutate', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(request) })
  } catch {
    throw new OperationError(0, 'NETWORK', 'The API could not be reached. Check that it is running, then try again.')
  }
  let body: unknown = null
  try { body = await response.json() } catch { /* not JSON */ }
  const record = body && typeof body === 'object' ? (body as Record<string, unknown>) : null
  if (!response.ok) {
    const code = typeof record?.code === 'string' ? record.code : 'FAILED'
    const message = typeof record?.error === 'string' ? record.error : `The API responded with status ${response.status}.`
    throw new OperationError(response.status, code, message)
  }
  if (!record || record.op !== request.op || record.source !== request.source || typeof record.path !== 'string') {
    throw new OperationError(response.status, 'UNEXPECTED', 'The API returned an unexpected response.')
  }
  return record as MutationResponse
}
/** Client-side name checks mirroring the server's shared validator; the server remains authoritative. */
export function validateName(name: string, kind: 'file' | 'folder'): string | null {
  if (name.length === 0) return 'Enter a name.'
  if (name.includes('/') || name.includes('\\')) return 'The name cannot contain / or \\ (create nested folders one at a time).'
  if (name.includes('\0')) return 'The name contains an invalid character.'
  if (name === '.' || name === '..') return 'That name is reserved.'
  const markdown = name.toLowerCase().endsWith('.md')
  if (kind === 'file' && !markdown) return 'The file name must end in .md.'
  if (kind === 'folder' && markdown) return 'A folder name cannot end in .md.'
  return null
}

