import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react'
import './App.css'
import { Breadcrumbs } from './graph/Breadcrumbs.tsx'
import { DocumentView } from './document/DocumentView.tsx'
import { ConfirmDialog } from './document/ConfirmDialog.tsx'
import type { EditingState } from './document/EditingSession.tsx'
import type { MutationResponse } from './operations/api.ts'
import { OperationDialog, type Operation } from './operations/OperationDialog.tsx'
import { useDocument } from './document/useDocument.ts'
import { GraphCanvas, type GraphCanvasHandle, type View, type ViewRequest } from './graph/GraphCanvas.tsx'
import { GraphLayout, type LayoutSnapshot } from './graph/layout.ts'
import { Outline } from './graph/Outline.tsx'
import {
  buildIndex,
  childCounts,
  collapseNode,
  descendantIds,
  describeCounts,
  fileToPathname,
  folderExists,
  folderToPathname,
  nodeId,
  parentFolderOf,
  parsePathname,
  pruneIds,
  refId,
  revealFolder,
  sameRef,
  visibleGraph,
  type Entry,
  type FileRef,
  type FolderRef,
  type GraphNode,
  type ParsedLocation,
  type TreeIndex,
} from './graph/model.ts'

type Data =
  | { status: 'loading' }
  | { status: 'error'; message: string }
  | { status: 'ready'; index: TreeIndex; refreshing: boolean; refreshError: string | null }

type Mode = 'graph' | 'outline'

/** Where the user was browsing when a document was opened, so Back to folder can restore it exactly. */
type ReturnContext = {
  pathname: string; location: ParsedLocation; focusId: string | null
  mode: Mode; expanded: string[]; layout: LayoutSnapshot; view: View | null; scroll: number
}
type HistoryEntry = { pathname: string; browsing?: ReturnContext; origin?: ReturnContext }

function fileName(ref: FileRef): string {
  return ref.path.slice(ref.path.lastIndexOf('/') + 1)
}

async function fetchEntries(signal?: AbortSignal): Promise<Entry[]> {
  const response = await fetch('/api/entries', { signal })
  let body: unknown = null
  try { body = await response.json() } catch { /* not JSON */ }
  const record = body && typeof body === 'object' ? (body as Record<string, unknown>) : null
  if (!response.ok) {
    throw new Error(typeof record?.error === 'string' ? record.error : `The API responded with status ${response.status}.`)
  }
  if (!record || !Array.isArray(record.entries)) throw new Error('The API returned an unexpected response.')
  return record.entries as Entry[]
}

function errorMessage(error: unknown): string {
  return error instanceof Error && error.message && error.name !== 'TypeError'
    ? error.message
    : 'The API could not be reached. Check that it is running.'
}

function summary(index: TreeIndex): string {
  let directories = 0
  let files = 0
  for (const node of index.nodes.values()) {
    if (node.kind === 'directory') directories += 1
    else if (node.kind === 'file') files += 1
  }
  return `${directories} ${directories === 1 ? 'folder' : 'folders'} and ${files} ${files === 1 ? 'Markdown file' : 'Markdown files'}`
}

const reducedMotionQuery = '(prefers-reduced-motion: reduce)'

function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState(() => window.matchMedia(reducedMotionQuery).matches)
  useEffect(() => {
    const query = window.matchMedia(reducedMotionQuery)
    const update = () => setReduced(query.matches)
    query.addEventListener('change', update)
    return () => query.removeEventListener('change', update)
  }, [])
  return reduced
}

function App() {
  const reducedMotion = usePrefersReducedMotion()
  const [layout] = useState(() => new GraphLayout({ synchronous: reducedMotion }))
  useEffect(() => { layout.setSynchronous(reducedMotion) }, [layout, reducedMotion])
  useEffect(() => () => layout.dispose(), [layout])

  const [data, setData] = useState<Data>({ status: 'loading' })
  const [expanded, setExpanded] = useState<ReadonlySet<string>>(() => new Set())
  const [location, setLocation] = useState<ParsedLocation>(() => parsePathname(window.location.pathname))
  const [mode, setMode] = useState<Mode>('graph')
  const [browsingRevision, setBrowsingRevision] = useState(0)
  const [announcement, setAnnouncement] = useState('')
  const [operation, setOperation] = useState<{ request: Operation; context: number } | null>(null)
  const [discardAction, setDiscardAction] = useState<{ run: () => void } | null>(null)
  const [viewRequest, setViewRequest] = useState<ViewRequest | null>(null)
  const canvasRef = useRef<GraphCanvasHandle>(null)
  const requestToken = useRef(0)
  const handledRequest = useRef(0)
  // Graph pan/zoom and outline scroll live here so they survive the workspace being replaced by a document.
  const viewStore = useRef<View | null>(null)
  const outlineScroll = useRef(0)
  // History carries only opaque keys; snapshots live in this page session, never across reloads.
  const [initialHistoryKey] = useState(() => crypto.randomUUID())
  const historyKey = useRef(initialHistoryKey)
  // Monotonic navigation context: leaving and returning to the same history entry still abandons async navigation.
  const navigationRevision = useRef(0)
  const historyEntries = useRef(new Map<string, HistoryEntry>())
  useLayoutEffect(() => {
    historyEntries.current.set(initialHistoryKey, { pathname: window.location.pathname })
    window.history.replaceState({ mdManager: initialHistoryKey }, '', window.location.pathname)
  }, [initialHistoryKey])
  const writeHistory = useCallback((entry: Omit<HistoryEntry, 'pathname'>, pathname: string, replace = false) => {
    navigationRevision.current += 1
    const key = replace ? historyKey.current : crypto.randomUUID()
    historyEntries.current.set(key, { ...entry, pathname })
    historyKey.current = key
    window.history[replace ? 'replaceState' : 'pushState']({ mdManager: key }, '', pathname)
  }, [])
  const pendingFocus = useRef<string | null>(null)
  // Mirrors of state for event handlers that must not re-subscribe on every change.
  const locationRef = useRef(location)
  const indexRef = useRef<TreeIndex | null>(null)
  useEffect(() => { locationRef.current = location }, [location])
  useEffect(() => { indexRef.current = data.status === 'ready' ? data.index : null }, [data])

  const requestView = useCallback((request: { type: 'fit' } | { type: 'reveal'; id: string }) => {
    requestToken.current += 1
    setViewRequest({ ...request, token: requestToken.current })
  }, [])

  const loadEntries = useCallback(async (signal?: AbortSignal) => {
    try {
      const entries = await fetchEntries(signal)
      if (signal?.aborted) return
      const index = buildIndex(entries)
      const current = locationRef.current
      if (current.kind === 'folder') {
        setExpanded(previous => revealFolder(index, previous, current.ref))
        requestView({ type: 'reveal', id: refId(current.ref) })
      }
      setData({ status: 'ready', index, refreshing: false, refreshError: null })
      // While a document is open its own load/failure announcements take precedence.
      if (current.kind !== 'file') setAnnouncement(`Loaded ${summary(index)}.`)
    } catch (error) {
      if (signal?.aborted) return
      setData({ status: 'error', message: errorMessage(error) })
      if (locationRef.current.kind !== 'file') setAnnouncement('Loading failed.')
    }
  }, [requestView])

  useEffect(() => {
    const controller = new AbortController()
    void loadEntries(controller.signal)
    return () => controller.abort()
  }, [loadEntries])

  const retry = useCallback(() => {
    setData({ status: 'loading' })
    setAnnouncement('Loading the Pi and Claude fixture folders.')
    void loadEntries()
  }, [loadEntries])

  /** Refetches the listing while keeping selection, expansion and pins. Resolves with the new index or null on failure. */
  const reloadListing = useCallback(async (): Promise<TreeIndex | null> => {
    setData(previous => (previous.status === 'ready' ? { ...previous, refreshing: true } : previous))
    try {
      const entries = await fetchEntries()
      const index = buildIndex(entries)
      setExpanded(previous => pruneIds(index, previous))
      layout.prune(new Set(index.nodes.keys()))
      indexRef.current = index
      setData({ status: 'ready', index, refreshing: false, refreshError: null })
      return index
    } catch (error) {
      const message = errorMessage(error)
      setData(previous => (previous.status === 'ready' ? { ...previous, refreshing: false, refreshError: message } : previous))
      return null
    }
  }, [layout])

  const refresh = useCallback(async () => {
    if (data.status !== 'ready' || data.refreshing) return
    setAnnouncement('Refreshing the listing.')
    const index = await reloadListing()
    if (!index) {
      setAnnouncement('Refresh failed. Showing the previous listing, which may be outdated.')
      return
    }
    const current = locationRef.current
    const missing = current.kind === 'folder' && !folderExists(index, current.ref)
    setAnnouncement(missing ? 'Refreshed. The selected folder no longer exists.' : `Refreshed: ${summary(index)}.`)
  }, [data, reloadListing])

  const captureBrowsing = useCallback((focusId: string | null = null): ReturnContext => ({
    pathname: historyEntries.current.get(historyKey.current)!.pathname, location: locationRef.current, focusId,
    mode, expanded: [...expanded], layout: layout.snapshot(),
    view: viewStore.current ? { ...viewStore.current } : null, scroll: outlineScroll.current,
  }), [mode, expanded, layout])
  const saveBrowsing = useCallback((focusId: string | null = null) => {
    if (locationRef.current.kind === 'file') return
    const entry = historyEntries.current.get(historyKey.current)!
    const snapshot = captureBrowsing(focusId ?? document.activeElement?.closest('[data-node-id]')?.getAttribute('data-node-id') ?? entry.browsing?.focusId ?? null)
    historyEntries.current.set(historyKey.current, { ...entry, browsing: snapshot })
    return snapshot
  }, [captureBrowsing])
  const restoreBrowsing = useCallback((context: ReturnContext) => {
    setBrowsingRevision(previous => previous + 1)
    layout.restore(context.layout)
    viewStore.current = context.view ? { ...context.view } : null
    outlineScroll.current = context.scroll
    setViewRequest(null)
    setMode(context.mode)
    setExpanded(new Set(context.expanded))
    setLocation(context.location)
    pendingFocus.current = context.focusId
  }, [layout])
  // popstate changes the URL first; the retained entry key still identifies the departing snapshot.
  const saveBrowsingRef = useRef(saveBrowsing)
  useLayoutEffect(() => { saveBrowsingRef.current = saveBrowsing }, [saveBrowsing])

  const navigate = useCallback((ref: FolderRef | null, options: { replace?: boolean; reveal?: boolean } = {}) => {
    const pathname = folderToPathname(ref)
    if (window.location.pathname !== pathname) {
      saveBrowsing()
      writeHistory({}, pathname, options.replace)
    }
    setLocation(ref ? { kind: 'folder', ref } : { kind: 'home' })
    const index = indexRef.current
    if (ref && options.reveal && index) {
      setExpanded(previous => revealFolder(index, previous, ref))
      requestView({ type: 'reveal', id: refId(ref) })
    } else if (!ref) {
      requestView({ type: 'fit' })
    }
  }, [requestView, saveBrowsing, writeHistory])

  useEffect(() => {
    const onPopState = (event: PopStateEvent) => {
      navigationRevision.current += 1
      setOperation(null)
      setDiscardAction(null)
      saveBrowsingRef.current()
      const entry = historyEntries.current.get(event.state?.mdManager)
      if (entry) historyKey.current = event.state.mdManager
      else {
        historyKey.current = crypto.randomUUID()
        writeHistory({}, window.location.pathname, true)
      }
      const context = entry?.browsing
      if (context) {
        restoreBrowsing(context)
        return
      }
      const next = parsePathname(window.location.pathname)
      setLocation(next)
      const index = indexRef.current
      if (next.kind === 'folder' && index) {
        setExpanded(previous => revealFolder(index, previous, next.ref))
        requestView({ type: 'reveal', id: refId(next.ref) })
      }
    }
    window.addEventListener('popstate', onPopState)
    return () => window.removeEventListener('popstate', onPopState)
  }, [requestView, restoreBrowsing, writeHistory])

  // ---- Documents ----
  const fileRef = location.kind === 'file' ? location.ref : null
  const { state: documentState, retry: retryDocument } = useDocument(fileRef, {
    onLoading: ref => setAnnouncement(`Loading ${fileName(ref)}.`),
    onLoaded: document => setAnnouncement(`Loaded ${fileName(document)}.`),
    onFailed: (ref, kind) => setAnnouncement(kind === 'missing' ? `${fileName(ref)} was not found.` : `Loading ${fileName(ref)} failed.`),
  })
  // Editing state of the open document, for navigation guards and file-operation eligibility.
  const [editingState, setEditingState] = useState<EditingState | null>(null)
  const editingRef = useRef<EditingState | null>(null)
  useEffect(() => { editingRef.current = editingState }, [editingState])
  const announce = useCallback((message: string) => setAnnouncement(message), [])
  const [pendingNotice, setPendingNotice] = useState(false)
  // The notice is derived: it only shows while the refused action's save is still pending.
  const showPendingNotice = pendingNotice && editingState?.pending === true
  /**
   * App-controlled actions that would abandon the editing session: refused while a save is pending,
   * confirmed while the draft is dirty, otherwise run immediately. Browser history is never intercepted.
   */
  const guardLeave = useCallback((leave: () => void) => {
    const editing = editingRef.current
    if (editing?.pending) {
      setPendingNotice(true)
      setAnnouncement('A save is in progress. Wait for it to finish before leaving this file.')
      return
    }
    if (editing?.dirty) {
      setDiscardAction({ run: leave })
      return
    }
    leave()
  }, [])
  const openFile = useCallback((node: GraphNode) => {
    if (node.kind !== 'file') return
    const ref: FileRef = { source: node.source, path: node.path }
    const pathname = fileToPathname(ref)
    const origin = saveBrowsingRef.current(node.id)
    pendingFocus.current = null
    writeHistory({ origin }, pathname)
    setLocation({ kind: 'file', ref })
  }, [writeHistory])

  const leaveFile = useCallback(() => {
    const current = locationRef.current
    if (current.kind !== 'file') return
    const context = historyEntries.current.get(historyKey.current)?.origin
    if (context) {
      // Restore the exact browsing entry: no fit, no re-expansion, no layout reset.
      writeHistory({ browsing: context }, context.pathname)
      restoreBrowsing(context)
    } else {
      // Direct link or reload: open the containing folder and reveal its ancestors.
      pendingFocus.current = nodeId(current.ref.source, current.ref.path)
      navigate(parentFolderOf(current.ref), { reveal: true })
    }
  }, [navigate, restoreBrowsing, writeHistory])
  const backToFolder = useCallback(() => guardLeave(leaveFile), [guardLeave, leaveFile])
  const navigateFromBreadcrumb = useCallback((ref: FolderRef | null) => guardLeave(() => navigate(ref, { reveal: true })), [guardLeave, navigate])

  // Focus the originating file action once the browsing view has rendered it again.
  useEffect(() => {
    const id = pendingFocus.current
    if (!id || location.kind === 'file') return
    const selector = `[data-node-id="${CSS.escape(id)}"]`
    const target = document.querySelector<HTMLElement | SVGElement>(`${selector} .node-body, ${selector} .outline-name`)
    if (target) {
      // Do not let keyboard-focus reveal or native scrolling alter a restored viewport/outline scroll.
      target.setAttribute('data-restoring-focus', 'true')
      target.focus({ preventScroll: true })
      target.removeAttribute('data-restoring-focus')
      pendingFocus.current = null
    }
  })

  // ---- File and folder operations ----
  const [operationNotice, setOperationNotice] = useState<string | null>(null)
  const [outcome, setOutcome] = useState<{ message: string; refreshFailed: boolean } | null>(null)
  const requestFolderOperation = useCallback((op: 'create-file' | 'create-folder' | 'rename' | 'move' | 'delete') => {
    const current = locationRef.current
    const ref: FolderRef | null = current.kind === 'folder' ? current.ref : null
    if (!ref) return
    setOperationNotice(null)
    if (op === 'create-file' || op === 'create-folder') setOperation({ request: { op, parent: ref }, context: navigationRevision.current })
    else if (ref.path) setOperation({ request: { op, target: { kind: 'folder', ref } }, context: navigationRevision.current })
  }, [])
  const requestFileOperation = useCallback((op: 'rename' | 'move' | 'delete' | 'copy') => {
    const current = locationRef.current
    if (current.kind !== 'file') return
    const editing = editingRef.current
    const name = fileName(current.ref)
    if (op !== 'copy' && editing && (editing.dirty || editing.pending || editing.conflicted)) {
      const reason = editing.pending ? 'a save is still pending' : editing.conflicted ? 'its draft conflicts with the file on disk' : 'it has unsaved changes'
      setOperationNotice(`${name} cannot be ${op === 'delete' ? 'deleted' : `${op}d`} while ${reason}. Save or discard the draft first; nothing is saved or discarded for you.`)
      setAnnouncement(`${name} has unsaved changes. Save or discard them first.`)
      return
    }
    if (op === 'copy' && editing?.pending) return
    setOperationNotice(null)
    const target = { kind: 'file' as const, ref: current.ref, draftDirty: editing?.dirty === true }
    setOperation({ request: op === 'copy' ? { op, target } : { op, target }, context: navigationRevision.current })
  }, [])
  const openCreatedFile = useCallback((ref: FileRef) => {
    const origin = saveBrowsingRef.current(null)
    pendingFocus.current = null
    writeHistory({ origin }, fileToPathname(ref))
    setLocation({ kind: 'file', ref })
  }, [writeHistory])
  const completeOperation = useCallback(async (done: Operation, response: MutationResponse, context: number) => {
    setOperation(current => current?.request === done ? null : current)
    // A successful request still refreshes the listing and reports its outcome after departure,
    // but can only navigate in its originating context, never over newer edits or pending saves.
    const follow = (action: () => void) => {
      const editing = editingRef.current
      if (navigationRevision.current !== context || editing?.dirty || editing?.pending || editing?.conflicted) return
      guardLeave(action)
    }
    const source = response.source
    const name = fileName({ source, path: response.path })
    const where = (path: string) => (path ? `${source} / ${path}` : source)
    let message: string
    // Identity changes of the open document are applied first so the document view never shows a stale path.
    if ((done.op === 'rename' || done.op === 'move') && done.target.kind === 'file' && response.destinationPath) {
      const ref: FileRef = { source, path: response.destinationPath }
      follow(() => {
        const entry = historyEntries.current.get(historyKey.current)
        writeHistory({ origin: entry?.origin }, fileToPathname(ref), true)
        setLocation({ kind: 'file', ref })
      })
    }
    const index = await reloadListing()
    switch (done.op) {
      case 'create-file': {
        message = `Created ${name} in ${where(response.path.slice(0, Math.max(0, response.path.lastIndexOf('/'))))}.`
        follow(() => openCreatedFile({ source, path: response.path }))
        break
      }
      case 'create-folder': {
        message = `Created folder ${name} in ${where(response.path.slice(0, Math.max(0, response.path.lastIndexOf('/'))))}.`
        if (index) follow(() => navigate({ source, path: response.path }, { reveal: true }))
        break
      }
      case 'rename':
      case 'move': {
        message = `${done.op === 'rename' ? 'Renamed' : 'Moved'} ${name} to ${where(response.destinationPath ?? response.path)}.`
        if (done.target.kind === 'folder' && response.destinationPath) {
          const path = response.destinationPath
          follow(() => navigate({ source, path }, { replace: true, reveal: true }))
        }
        break
      }
      case 'delete': {
        message = `Deleted ${name} from ${where(response.path.slice(0, Math.max(0, response.path.lastIndexOf('/'))))}.`
        const parent: FolderRef = { source, path: response.path.slice(0, Math.max(0, response.path.lastIndexOf('/'))) }
        follow(() => {
          pendingFocus.current = refId(parent)
          navigate(parent, { reveal: true })
        })
        break
      }
      case 'copy':
        message = `Copied ${name} to ${response.destinationSource} / ${response.destinationPath}.`
        break
    }
    setOutcome({ message, refreshFailed: index === null })
    setAnnouncement(index === null ? `${message} The listing could not be refreshed.` : message)
  }, [guardLeave, navigate, openCreatedFile, reloadListing, writeHistory])

  const index = data.status === 'ready' ? data.index : null
  const selectedRef = location.kind === 'folder' ? location.ref : null
  const selectedExists = index !== null && selectedRef !== null && folderExists(index, selectedRef)
  const selectedId = selectedExists && selectedRef ? refId(selectedRef) : null
  const visible = useMemo(() => (index ? visibleGraph(index, expanded) : { nodes: [], edges: [] }), [index, expanded])

  const select = useCallback((node: GraphNode) => {
    const ref = { source: node.source, path: node.path }
    if (sameRef(locationRef.current.kind === 'folder' ? locationRef.current.ref : null, ref)) return
    navigate(ref)
  }, [navigate])

  const toggleExpand = useCallback((node: GraphNode) => {
    if (!index) return
    if (expanded.has(node.id)) {
      setExpanded(collapseNode(index, expanded, node.id))
      const current = locationRef.current
      if (current.kind === 'folder' && descendantIds(index, node.id).includes(refId(current.ref))) {
        navigate({ source: node.source, path: node.path }, { replace: true })
      }
      setAnnouncement(`Collapsed ${node.name}.`)
    } else {
      setExpanded(new Set(expanded).add(node.id))
      setAnnouncement(`Expanded ${node.name}: ${describeCounts(childCounts(index, node.id))}`)
    }
  }, [index, expanded, navigate])

  const togglePin = useCallback((node: GraphNode) => {
    const wasPinned = layout.isPinned(node.id)
    layout.togglePin(node.id)
    setAnnouncement(`${wasPinned ? 'Unpinned' : 'Pinned'} ${node.name}.`)
  }, [layout])

  const reset = useCallback(() => {
    layout.reset()
    setExpanded(new Set())
    navigate(null)
    setAnnouncement('Reset: showing the Pi and Claude sources.')
  }, [layout, navigate])

  const toggleMode = useCallback(() => {
    setMode(previous => {
      const next = previous === 'graph' ? 'outline' : 'graph'
      setAnnouncement(next === 'outline' ? 'Outline view.' : 'Graph view.')
      return next
    })
  }, [])

  const ready = data.status === 'ready'
  const refreshing = data.status === 'ready' && data.refreshing
  const graphControlsEnabled = ready && mode === 'graph'
  const browsing = fileRef === null

  let missingNotice: React.ReactNode = null
  if (index && location.kind === 'unknown-source') {
    missingNotice = <>Source “{location.name}” does not exist. Only the Pi and Claude sources are available.</>
  } else if (index && location.kind === 'malformed') {
    missingNotice = <>This link is invalid and could not be read.</>
  } else if (index && selectedRef && !selectedExists) {
    missingNotice = <>Folder “{selectedRef.path || selectedRef.source}” was not found in {selectedRef.source}. It may have been renamed or removed.</>
  }

  return (
    <div className="app">
      <header className="app-header">
        <div className="app-title">
          <h1>MD Manager</h1>
          <p>Pi and Claude fixture folders as a containment graph. Edits are saved only when you press Save.</p>
        </div>
        <button type="button" className="button" onClick={() => void refresh()} disabled={!ready || refreshing} aria-busy={refreshing}>
          {refreshing ? 'Refreshing…' : 'Refresh'}
        </button>
      </header>

      <div className="visually-hidden" role="status" aria-live="polite">{announcement}</div>

      {showPendingNotice && (
        <div className="banner banner-error" role="alert">
          A save is in progress. Wait for it to finish before leaving this file; if it fails you can retry or copy the draft.
        </div>
      )}
      {discardAction && (
        <ConfirmDialog title="Discard changes?" confirmLabel="Discard" destructive onConfirm={() => { const action = discardAction; setDiscardAction(null); action.run() }} onCancel={() => setDiscardAction(null)}>
          <p>This file has unsaved changes. Leaving now discards them; they cannot be recovered afterwards. Cancel to keep editing, or save first.</p>
        </ConfirmDialog>
      )}

      {operationNotice && (
        <div className="banner banner-error" role="alert">
          {operationNotice}
          <button type="button" className="button button-small" onClick={() => setOperationNotice(null)}>Dismiss</button>
        </div>
      )}
      {outcome && (outcome.refreshFailed ? (
        <div className="banner banner-error" role="alert" data-testid="operation-outcome">
          {outcome.message} The listing could not be refreshed afterwards, so the graph may be outdated: use Refresh once the API is reachable. Do not repeat the operation.
          <button type="button" className="button button-small" onClick={() => { setOutcome(null); void refresh() }} disabled={!ready}>Refresh</button>
          <button type="button" className="button button-small" onClick={() => setOutcome(null)}>Dismiss</button>
        </div>
      ) : (
        <div className="banner banner-info" data-testid="operation-outcome">
          {outcome.message}
          <button type="button" className="button button-small" onClick={() => setOutcome(null)}>Dismiss</button>
        </div>
      ))}
      {operation && index && (
        <OperationDialog operation={operation.request} index={index} onCancel={() => setOperation(null)} onSuccess={(done, response) => { void completeOperation(done, response, operation.context) }} />
      )}

      {data.status === 'ready' && data.refreshError && !outcome?.refreshFailed && (
        <div className="banner banner-error" role="alert">
          Refresh failed: {data.refreshError} The graph still shows the previous listing, which may be outdated. Try Refresh again once the API and fixture folders are available.
        </div>
      )}

      <div className="navigation">
        <Breadcrumbs selected={selectedRef} file={fileRef} onNavigate={navigateFromBreadcrumb} />
        {fileRef ? null : missingNotice ? (
          <div className="missing" role="alert">
            <p>{missingNotice}</p>
            <p className="missing-links">
              {selectedRef && location.kind === 'folder'
                ? <a href={folderToPathname({ source: selectedRef.source, path: '' })} onClick={event => { event.preventDefault(); navigate({ source: selectedRef.source, path: '' }, { reveal: true }) }}>Go to the {selectedRef.source} root</a>
                : <>
                    <a href="/Pi" onClick={event => { event.preventDefault(); navigate({ source: 'Pi', path: '' }, { reveal: true }) }}>Go to the Pi root</a>
                    <a href="/Claude" onClick={event => { event.preventDefault(); navigate({ source: 'Claude', path: '' }, { reveal: true }) }}>Go to the Claude root</a>
                  </>}
              <a href="/" onClick={event => { event.preventDefault(); navigate(null) }}>Home</a>
            </p>
          </div>
        ) : (
          <p className="folder-info" data-testid="folder-info">
            {index && selectedId
              ? describeCounts(childCounts(index, selectedId))
              : 'Two sources: Pi and Claude. Select a source or folder to see what it contains.'}
          </p>
        )}
      </div>

      {browsing && (
        <div className="toolbars">
          <div className="toolbar" role="toolbar" aria-label="Graph controls">
            <button type="button" className="button" onClick={() => canvasRef.current?.zoomIn()} disabled={!graphControlsEnabled} aria-label="Zoom in">+</button>
            <button type="button" className="button" onClick={() => canvasRef.current?.zoomOut()} disabled={!graphControlsEnabled} aria-label="Zoom out">−</button>
            <button type="button" className="button" onClick={() => canvasRef.current?.fit()} disabled={!graphControlsEnabled}>Fit</button>
            <button type="button" className="button" onClick={reset} disabled={!ready}>Reset</button>
            <button type="button" className="button" onClick={toggleMode} disabled={!ready} aria-pressed={mode === 'outline'}>Outline</button>
          </div>
          <div className="toolbar" role="toolbar" aria-label="File operations">
            <button type="button" className="button" onClick={() => requestFolderOperation('create-file')} disabled={!selectedExists}>New file…</button>
            <button type="button" className="button" onClick={() => requestFolderOperation('create-folder')} disabled={!selectedExists}>New folder…</button>
            <button type="button" className="button" onClick={() => requestFolderOperation('rename')} disabled={!selectedExists || !selectedRef?.path}>Rename…</button>
            <button type="button" className="button" onClick={() => requestFolderOperation('move')} disabled={!selectedExists || !selectedRef?.path}>Move…</button>
            <button type="button" className="button" onClick={() => requestFolderOperation('delete')} disabled={!selectedExists || !selectedRef?.path}>Delete…</button>
          </div>
        </div>
      )}

      <main className={browsing ? 'workspace' : 'workspace workspace-document'} aria-busy={browsing && data.status === 'loading'}>
        {fileRef && documentState && (
          <DocumentView
            fileRef={fileRef}
            state={documentState}
            editingState={editingState}
            onBack={backToFolder}
            onRetry={retryDocument}
            onAnnounce={announce}
            onEditingChange={setEditingState}
            onOperation={requestFileOperation}
            guardLeave={guardLeave}
          />
        )}
        {browsing && data.status === 'loading' && (
          <div className="placeholder">
            <p>Loading the Pi and Claude fixture folders…</p>
          </div>
        )}
        {browsing && data.status === 'error' && (
          <div className="placeholder" role="alert">
            <p>Unable to load the fixture folders. {data.message}</p>
            <p>Check that the API is running and both fixture folders are readable, then retry.</p>
            <button type="button" className="button" onClick={retry}>Retry</button>
          </div>
        )}
        {browsing && data.status === 'ready' && mode === 'graph' && (
          <GraphCanvas
            key={browsingRevision}
            ref={canvasRef}
            layout={layout}
            index={data.index}
            nodes={visible.nodes}
            edges={visible.edges}
            expanded={expanded}
            selectedId={selectedId}
            viewRequest={viewRequest}
            handledRequest={handledRequest}
            viewStore={viewStore}
            onSelect={select}
            onOpenFile={openFile}
            onToggleExpand={toggleExpand}
            onTogglePin={togglePin}
          />
        )}
        {browsing && data.status === 'ready' && mode === 'outline' && (
          <Outline
            key={browsingRevision}
            index={data.index}
            expanded={expanded}
            selectedId={selectedId}
            scrollRef={outlineScroll}
            onSelect={select}
            onOpenFile={openFile}
            onToggleExpand={toggleExpand}
          />
        )}
      </main>

      {browsing && mode === 'graph' && (
        <footer className="legend" aria-label="Legend">
          <ul>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><circle className="legend-source" r="11" /></svg>Source</li>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><path className="legend-directory" d="M -12 -9 h 7 l 3 3 h 14 v 15 h -24 z" /></svg>Folder</li>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><path className="legend-file" d="M -7 -11 h 9 l 5 5 v 17 h -14 z" /></svg>Markdown file</li>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><line className="legend-edge" x1="-13" y1="0" x2="8" y2="0" markerEnd="url(#contains-arrow)" /><path className="legend-edge-arrow" d="M 7 -4 L 13 0 L 7 4 z" /></svg>Contains (parent → child)</li>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><circle className="legend-pin" r="9" /><path className="legend-pin-glyph" d="M -3 -4 h 6 l -1 4 h -4 z M 0 0 v 6" /></svg>Pinned (dragged or P)</li>
          </ul>
          <p>Keyboard: Tab moves through nodes in outline order, Enter selects a folder or opens a file, → expands, ← collapses, P pins or unpins.</p>
        </footer>
      )}
    </div>
  )
}

export default App

import { useMemo, useState, type FormEvent } from 'react'
import { nodeId, type FolderRef, type Source, type TreeIndex } from '../graph/model.ts'
import { Modal } from '../ui/Modal.tsx'
import { OperationError, performOperation, type MutationRequest, type MutationResponse } from './api.ts'
import { validateName } from './validate.ts'

/** What the user asked to do and to what. Folders use `kind: 'folder'`; a source root is a folder with path ''. */
export type OperationTarget =
  | { kind: 'folder'; ref: FolderRef }
  | { kind: 'file'; ref: { source: Source; path: string }; draftDirty: boolean }

export type Operation =
  | { op: 'create-file' | 'create-folder'; parent: FolderRef }
  | { op: 'rename' | 'move' | 'delete'; target: OperationTarget }
  | { op: 'copy'; target: Extract<OperationTarget, { kind: 'file' }> }

type Props = {
  operation: Operation
  index: TreeIndex
  onCancel: () => void
  onSuccess: (operation: Operation, response: MutationResponse) => void
}

function baseName(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1)
}

function parentPath(path: string): string {
  const cut = path.lastIndexOf('/')
  return cut === -1 ? '' : path.slice(0, cut)
}

function describeFolder(ref: FolderRef): string {
  return ref.path ? `${ref.source} / ${ref.path}` : ref.source
}

function joinPath(parent: string, name: string): string {
  return parent ? `${parent}/${name}` : name
}

/** Folders of one source, in listing order, optionally excluding a subtree (a folder cannot move into itself). */
function folderOptions(index: TreeIndex, source: Source, exclude: string | null): FolderRef[] {
  const options: FolderRef[] = []
  for (const node of index.nodes.values()) {
    if (node.source !== source || node.kind === 'file') continue
    if (exclude !== null && (node.path === exclude || node.path.startsWith(`${exclude}/`))) continue
    options.push({ source, path: node.path })
  }
  return options.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))
}

const TITLES: Record<Operation['op'], string> = {
  'create-file': 'New file', 'create-folder': 'New folder', rename: 'Rename', move: 'Move', delete: 'Delete', copy: 'Copy',
}
const SUBMIT: Record<Operation['op'], string> = {
  'create-file': 'Create', 'create-folder': 'Create', rename: 'Rename', move: 'Move', delete: 'Delete', copy: 'Copy',
}

/** One labelled dialog per operation: name/destination fields, client validation, one pending request, server errors inline. */
export function OperationDialog({ operation, index, onCancel, onSuccess }: Props) {
  const { op } = operation
  const target = 'target' in operation ? operation.target : null
  const targetName = target ? baseName(target.ref.path) : ''
  const nameKind: 'file' | 'folder' = op === 'create-folder' || (target?.kind === 'folder') ? 'folder' : 'file'
  const [name, setName] = useState(op === 'rename' || op === 'copy' ? targetName : '')
  const destinationSource: Source | null = op === 'copy' ? (operation.target.ref.source === 'Pi' ? 'Claude' : 'Pi') : op === 'move' ? operation.target.ref.source : null
  const destinations = useMemo(() => {
    if (!destinationSource) return []
    const exclude = op === 'move' && operation.target.kind === 'folder' ? operation.target.ref.path : null
    const currentParent = op === 'move' ? parentPath(operation.target.ref.path) : null
    return folderOptions(index, destinationSource, exclude).filter(folder => folder.path !== currentParent)
  }, [destinationSource, index, op, operation])
  const [destination, setDestination] = useState(() => destinations[0]?.path ?? '')
  const [error, setError] = useState<string | null>(null)
  const [pending, setPending] = useState(false)

  const request = (): MutationRequest | string => {
    switch (op) {
      case 'create-file':
      case 'create-folder': {
        const invalid = validateName(name, nameKind)
        if (invalid) return invalid
        return { op, source: operation.parent.source, path: joinPath(operation.parent.path, name) }
      }
      case 'rename': {
        const invalid = validateName(name, nameKind)
        if (invalid) return invalid
        if (name === targetName) return 'Enter a different name.'
        return { op, source: operation.target.ref.source, path: operation.target.ref.path, destinationPath: joinPath(parentPath(operation.target.ref.path), name) }
      }
      case 'move': {
        if (destinations.length === 0) return 'There is no other folder to move this into.'
        return { op, source: operation.target.ref.source, path: operation.target.ref.path, destinationPath: joinPath(destination, targetName) }
      }
      case 'delete':
        return { op, source: operation.target.ref.source, path: operation.target.ref.path }
      case 'copy': {
        const invalid = validateName(name, 'file')
        if (invalid) return invalid
        return { op, source: operation.target.ref.source, path: operation.target.ref.path, destinationSource: destinationSource!, destinationPath: joinPath(destination, name) }
      }
    }
  }

  const submit = async (event: FormEvent) => {
    event.preventDefault()
    if (pending) return
    const built = request()
    if (typeof built === 'string') { setError(built); return }
    setError(null)
    setPending(true)
    try {
      const response = await performOperation(built)
      onSuccess(operation, response)
    } catch (failure) {
      setError(failure instanceof OperationError ? failure.message : 'The operation failed unexpectedly.')
      setPending(false)
    }
  }

  let description: React.ReactNode
  let fields: React.ReactNode = null
  const destinationField = destinationSource && (
    <label className="field">
      <span>Destination folder</span>
      <select value={destination} onChange={event => setDestination(event.target.value)} disabled={pending || destinations.length === 0} aria-label="Destination folder">
        {destinations.map(folder => (
          <option key={nodeId(folder.source, folder.path)} value={folder.path}>{folder.path || `${folder.source} (source root)`}</option>
        ))}
      </select>
    </label>
  )
  switch (op) {
    case 'create-file':
    case 'create-folder':
      description = <p>In <span className="dialog-path">{describeFolder(operation.parent)}</span>. {op === 'create-file' ? 'The file starts empty and opens for editing.' : 'The folder starts empty.'}</p>
      fields = (
        <label className="field">
          <span>{op === 'create-file' ? 'File name' : 'Folder name'}</span>
          <input type="text" value={name} onChange={event => setName(event.target.value)} disabled={pending} placeholder={op === 'create-file' ? 'name.md' : 'name'} autoComplete="off" spellCheck={false} />
        </label>
      )
      break
    case 'rename':
      description = <p>Renames <span className="dialog-path">{describeFolder({ source: operation.target.ref.source, path: operation.target.ref.path })}</span> within its folder.</p>
      fields = (
        <label className="field">
          <span>New name</span>
          <input type="text" value={name} onChange={event => setName(event.target.value)} disabled={pending} autoComplete="off" spellCheck={false} />
        </label>
      )
      break
    case 'move':
      description = <p>Moves <span className="dialog-path">{describeFolder({ source: operation.target.ref.source, path: operation.target.ref.path })}</span> to another folder in {operation.target.ref.source}, keeping its name.</p>
      fields = destinationField
      break
    case 'delete':
      description = (
        <>
          <p>Delete <span className="dialog-path">{operation.target.ref.source} / {operation.target.ref.path}</span>?</p>
          <p>This cannot be undone in the app: there is no trash or version history, only whatever git or backups hold. {operation.target.kind === 'folder' ? 'Only an empty folder can be deleted.' : ''}</p>
        </>
      )
      break
    case 'copy':
      description = (
        <>
          <p>Copies the <strong>saved content</strong> of <span className="dialog-path">{operation.target.ref.source} / {operation.target.ref.path}</span> from disk into {destinationSource}{operation.target.draftDirty ? '; unsaved draft changes are not included' : ''}.</p>
          <p>The bytes are copied as they are, so frontmatter written for {operation.target.ref.source} may not be accepted by the {destinationSource} agent.</p>
        </>
      )
      fields = (
        <>
          {destinationField}
          <label className="field">
            <span>File name</span>
            <input type="text" value={name} onChange={event => setName(event.target.value)} disabled={pending} autoComplete="off" spellCheck={false} />
          </label>
        </>
      )
      break
  }

  const destructive = op === 'delete'
  return (
    <Modal title={op === 'copy' ? `Copy to ${destinationSource}` : TITLES[op]} initialFocus={fields ? 'first-field' : destructive ? 'cancel' : 'confirm'} pending={pending} onCancel={onCancel}>
      <form method="dialog" onSubmit={event => { void submit(event) }} aria-busy={pending}>
        <div className="confirm-description">{description}</div>
        {fields}
        {error && <p className="dialog-error" role="alert">{error}</p>}
        <div className="confirm-actions">
          <button type="button" className="button" data-dialog-cancel onClick={onCancel} disabled={pending}>Cancel</button>
          <button type="submit" className={destructive ? 'button button-danger' : 'button'} data-dialog-confirm disabled={pending} aria-busy={pending}>
            {pending ? `${SUBMIT[op]}…` : SUBMIT[op]}
          </button>
        </div>
      </form>
    </Modal>
  )
}

import { useCallback, useEffect, useRef, useState, type KeyboardEvent } from 'react'
import { fileToPathname, type FileRef } from '../graph/model.ts'
import { EditingSession, type EditingState } from './EditingSession.tsx'
import type { Snapshot } from './editSession.ts'
import { Markdown } from './Markdown.tsx'
import { analyzeText, contentHash, type TextAnalysis } from './serialize.ts'
import type { DocumentState } from './useDocument.ts'

type Tab = 'rendered' | 'source'
const TABS: ReadonlyArray<{ id: Tab; label: string }> = [
  { id: 'rendered', label: 'Rendered' },
  { id: 'source', label: 'Source' },
]

type Props = {
  fileRef: FileRef
  state: DocumentState
  onBack: () => void
  onRetry: () => void
  onAnnounce: (message: string) => void
  onEditingChange: (state: EditingState | null) => void
  /** Current editing state, for copy labelling and disabling while a save is pending. */
  editingState: EditingState | null
  onOperation: (op: 'rename' | 'move' | 'delete' | 'copy') => void
  guardLeave: (leave: () => void) => void
}

/** Whether the loaded text can be edited and written back byte for byte. */
type Editability =
  | { status: 'checking' }
  | { status: 'editable'; analysis: TextAnalysis }
  | { status: 'unavailable'; reason: string }

function baseName(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1)
}

/** Document shell: identity header, Back to folder, Rendered/Source tabs, load states, and the editing session. */
export function DocumentView({ fileRef, state, editingState, onBack, onRetry, onAnnounce, onEditingChange, onOperation, guardLeave }: Props) {
  const key = fileToPathname(fileRef)
  const name = baseName(fileRef.path)
  const otherSource = fileRef.source === 'Pi' ? 'Claude' : 'Pi'
  const headingRef = useRef<HTMLHeadingElement>(null)
  const editButtonRef = useRef<HTMLButtonElement>(null)
  const tabRefs = useRef<Array<HTMLButtonElement | null>>([])
  const [tab, setTab] = useState<Tab>('rendered')
  const [editing, setEditing] = useState(false)
  // After editing, the read-only view shows the last acknowledged content, not the original fetch.
  const [override, setOverride] = useState<{ ref: FileRef; document: Snapshot } | null>(null)
  const [tabKey, setTabKey] = useState(key)
  // Opening a different document always starts on Rendered, read-only.
  if (tabKey !== key) {
    setTabKey(key)
    setTab('rendered')
    setEditing(false)
    setOverride(null)
  }

  const loaded = state.status === 'ready' ? state.document : null
  const shown: Snapshot | null = loaded ? (override && override.ref === state.ref ? override.document : loaded) : null

  // Focus moves to the document entry point when a document is opened (not when switching tabs).
  useEffect(() => { headingRef.current?.focus() }, [key])

  // Editability: same line ending throughout, and the UTF-8 re-encoding must hash to the bytes the server read.
  // The hash check is asynchronous; until it settles for this exact document, editing is unavailable.
  const [hashCheck, setHashCheck] = useState<{ document: Snapshot; matches: boolean } | null>(null)
  useEffect(() => {
    if (!shown) return
    let cancelled = false
    void contentHash(shown.content).then(hash => { if (!cancelled) setHashCheck({ document: shown, matches: hash === shown.hash }) })
    return () => { cancelled = true }
  }, [shown])
  let editability: Editability = { status: 'checking' }
  if (shown && hashCheck?.document === shown) {
    const analysis = analyzeText(shown.content)
    if (!analysis.editable) editability = { status: 'unavailable', reason: analysis.reason }
    else if (!hashCheck.matches) editability = { status: 'unavailable', reason: 'it is not valid UTF-8, so its bytes cannot be reproduced' }
    else editability = { status: 'editable', analysis }
  }

  const acknowledged = useCallback((snapshot: Snapshot) => {
    setOverride(previous => (previous && previous.ref === state.ref && previous.document === snapshot ? previous : { ref: state.ref, document: snapshot }))
  }, [state.ref])
  const exitEditing = useCallback((acknowledged: Snapshot) => {
    setOverride({ ref: state.ref, document: acknowledged })
    setEditing(false)
    setTab('rendered')
    onAnnounce(`Finished editing ${name}.`)
    requestAnimationFrame(() => editButtonRef.current?.focus())
  }, [name, onAnnounce, state.ref])

  const onTabKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    const index = TABS.findIndex(candidate => candidate.id === tab)
    let next: number | null = null
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown') next = (index + 1) % TABS.length
    else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') next = (index - 1 + TABS.length) % TABS.length
    else if (event.key === 'Home') next = 0
    else if (event.key === 'End') next = TABS.length - 1
    if (next === null) return
    event.preventDefault()
    setTab(TABS[next].id)
    tabRefs.current[next]?.focus()
  }

  let panel: React.ReactNode
  if (state.status === 'loading') {
    panel = <p className="document-message">Loading {name}…</p>
  } else if (state.status === 'error') {
    const explanation = state.kind === 'missing'
      ? `${name} was not found in ${fileRef.source} or is unavailable. It may have been renamed or removed.`
      : state.kind === 'invalid'
        ? `The link to ${name} is invalid.`
        : `${name} could not be loaded. ${state.message}`
    panel = (
      <div className="document-message document-error" role="alert">
        <p>{explanation}</p>
        <p className="document-actions">
          {state.kind === 'failed' && <button type="button" className="button" onClick={onRetry}>Retry</button>}
          <span>Use Back to folder to return to browsing.</span>
        </p>
      </div>
    )
  } else if (shown) {
    // Keep the memoized Markdown subtree mounted across tab switches: large files should not be
    // parsed again just to return from Source. Only the selected tab is visible/accessibility-exposed.
    panel = (
      <>
        <div hidden={tab !== 'rendered'}>
          {shown.content === ''
            ? <p className="document-message">This file is empty.</p>
            : <Markdown content={shown.content} />}
        </div>
        {tab === 'source' && <>
          {shown.content === '' && <p className="document-message">This file is empty.</p>}
          <pre className="document-source" data-testid="document-source" tabIndex={0}>{shown.content}</pre>
        </>}
      </>
    )
  }

  const canEdit = shown !== null && editability.status === 'editable'
  const body = editing && shown
    ? (
      <div className="document-editing">
        <EditingSession
          key={key}
          fileRef={fileRef}
          document={shown}
          analysis={editability.status === 'editable' ? editability.analysis : analyzeText(shown.content)}
          onAnnounce={onAnnounce}
          onStateChange={onEditingChange}
          onAcknowledged={acknowledged}
          guardLeave={guardLeave}
          onExit={exitEditing}
        />
      </div>
    )
    : (
      <>
        <div className="tabs" role="tablist" aria-label="Document view">
          {TABS.map((candidate, index) => (
            <button
              key={candidate.id}
              ref={element => { tabRefs.current[index] = element }}
              type="button"
              role="tab"
              id={`tab-${candidate.id}`}
              className="tab"
              aria-selected={tab === candidate.id}
              aria-controls="document-panel"
              tabIndex={tab === candidate.id ? 0 : -1}
              onClick={() => setTab(candidate.id)}
              onKeyDown={onTabKeyDown}
            >
              {candidate.label}
            </button>
          ))}
        </div>
        <div className="document-panel" role="tabpanel" id="document-panel" aria-labelledby={`tab-${tab}`}>
          {panel}
        </div>
      </>
    )
  return (
    <section
      className="document"
      data-testid="document-view"
      data-hash={shown?.hash}
      aria-labelledby="document-title"
      aria-busy={state.status === 'loading'}
    >
      <header className="document-header">
        <div className="document-identity">
          <h2 id="document-title" ref={headingRef} tabIndex={-1}>{name}</h2>
          <p className="document-meta" data-testid="document-meta">
            <span className="document-source-name">{fileRef.source}</span>
            <span className="document-separator" aria-hidden="true">·</span>
            <span className="document-path">{fileRef.path}</span>
          </p>
        </div>
        <div className="document-header-actions">
          {shown && (
            <>
              <button type="button" className="button" onClick={() => onOperation('rename')}>Rename…</button>
              <button type="button" className="button" onClick={() => onOperation('move')}>Move…</button>
              <button type="button" className="button" onClick={() => onOperation('delete')}>Delete…</button>
              <button type="button" className="button" onClick={() => onOperation('copy')} disabled={editingState?.pending === true} title={editingState?.pending ? 'Wait for the save to finish.' : undefined}>
                {editingState?.dirty ? `Copy saved content to ${otherSource}…` : `Copy to ${otherSource}…`}
              </button>
            </>
          )}
          {shown && !editing && (
            <button
              ref={editButtonRef}
              type="button"
              className="button"
              onClick={() => setEditing(true)}
              disabled={!canEdit}
              aria-describedby={editability.status === 'unavailable' ? 'edit-unavailable' : undefined}
            >
              Edit
            </button>
          )}
          <button type="button" className="button" onClick={onBack}>Back to folder</button>
        </div>
      </header>
      {shown && !editing && editability.status === 'unavailable' && (
        <p className="document-notice" id="edit-unavailable" data-testid="edit-unavailable">
          This file is read-only here because {editability.reason}. Editing it in this app could not keep the file byte for byte.
        </p>
      )}
      {body}
    </section>
  )
}

import { useLayoutEffect, useRef, type MutableRefObject } from 'react'
import { childCounts, childrenOf, describeCounts, SOURCES, type GraphNode, type TreeIndex } from './model.ts'

type Props = {
  index: TreeIndex
  expanded: ReadonlySet<string>
  selectedId: string | null
  /** Scroll position survives unmounting (graph mode, document view) through this owner-held store. */
  scrollRef: MutableRefObject<number>
  onSelect: (node: GraphNode) => void
  onOpenFile: (node: GraphNode) => void
  onToggleExpand: (node: GraphNode) => void
}

/** Accessible replacement for the graph: the same tree, expansion state and selection as nested lists. */
export function Outline({ index, expanded, selectedId, scrollRef, onSelect, onOpenFile, onToggleExpand }: Props) {
  const container = useRef<HTMLElement>(null)
  useLayoutEffect(() => {
    if (container.current) container.current.scrollTop = scrollRef.current
  }, [scrollRef])

  function renderFolder(node: GraphNode) {
    const isExpanded = expanded.has(node.id)
    const counts = childCounts(index, node.id)
    const children = childrenOf(index, node.id)
    return (
      <li key={node.id} className={`outline-item outline-${node.kind}`} data-node-id={node.id}>
        <div className="outline-row">
          <button
            type="button"
            className="outline-toggle"
            aria-expanded={isExpanded}
            aria-label={`${isExpanded ? 'Collapse' : 'Expand'} ${node.name}`}
            onClick={() => onToggleExpand(node)}
          >
            <svg viewBox="0 0 10 10" width="10" height="10" aria-hidden="true">
              <path d={isExpanded ? 'M 1 3 L 5 7 L 9 3' : 'M 3 1 L 7 5 L 3 9'} />
            </svg>
          </button>
          <button
            type="button"
            className="outline-name"
            aria-current={node.id === selectedId ? 'true' : undefined}
            onClick={() => onSelect(node)}
          >
            <span className="outline-icon" aria-hidden="true">{node.kind === 'source' ? '◎' : '▰'}</span>
            <span>{node.name}</span>
            <span className="visually-hidden">, {node.kind === 'source' ? 'source folder' : 'folder'}</span>
          </button>
          <span className="outline-counts">{describeCounts(counts)}</span>
        </div>
        {isExpanded && (
          <ul className="outline-list">
            {children.length === 0
              ? <li className="outline-empty">This folder is empty.</li>
              : children.map(child => (child.kind === 'file' ? renderFile(child) : renderFolder(child)))}
          </ul>
        )}
      </li>
    )
  }

  function renderFile(node: GraphNode) {
    return (
      <li key={node.id} className="outline-item outline-file" data-node-id={node.id}>
        <div className="outline-row">
          <button type="button" className="outline-name outline-file-name" onClick={() => onOpenFile(node)}>
            <span className="outline-icon" aria-hidden="true">▤</span>
            <span>{node.name}</span>
            <span className="visually-hidden">, Markdown file</span>
          </button>
        </div>
      </li>
    )
  }

  return (
    <nav
      className="outline"
      aria-label="Directory outline"
      ref={container}
      onScroll={event => { scrollRef.current = event.currentTarget.scrollTop }}
    >
      <ul className="outline-list outline-root">
        {SOURCES.map(source => renderFolder(index.nodes.get(source)!))}
      </ul>
    </nav>
  )
}

import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useReducer,
  useRef,
  useState,
  type KeyboardEvent,
  type MutableRefObject,
  type PointerEvent as ReactPointerEvent,
} from 'react'
import { childCounts, describeCounts, type GraphEdge, type GraphNode, type TreeIndex } from './model.ts'
import { GraphLayout, NODE_RADIUS, type Point } from './layout.ts'
import { wrapLabel } from './labels.ts'

export type ViewRequest = { token: number; type: 'fit' } | { token: number; type: 'reveal'; id: string }

export type GraphCanvasHandle = { zoomIn(): void; zoomOut(): void; fit(): void }

export type View = { x: number; y: number; k: number }

/** Pan/zoom survives unmounting (outline mode, document view) through this owner-held store. */
export type ViewStore = MutableRefObject<View | null>

type Props = {
  layout: GraphLayout
  index: TreeIndex
  nodes: GraphNode[]
  edges: GraphEdge[]
  expanded: ReadonlySet<string>
  selectedId: string | null
  viewRequest: ViewRequest | null
  /** Token of the last request any canvas instance handled, so a remount never replays an old fit/reveal. */
  handledRequest: MutableRefObject<number>
  viewStore: ViewStore
  onSelect: (node: GraphNode) => void
  onOpenFile: (node: GraphNode) => void
  onToggleExpand: (node: GraphNode) => void
  onTogglePin: (node: GraphNode) => void
}

const MIN_ZOOM = 0.15
const MAX_ZOOM = 3
const DRAG_THRESHOLD = 4
const FIT_PADDING = 70

function clampZoom(k: number) {
  return Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, k))
}

type NodeBox = { halfWidth: number; top: number; bottom: number }

/** Distance from a node's centre to the edge of its box (shape plus label) along a unit direction. */
function reach(box: NodeBox, ux: number, uy: number): number {
  const tx = Math.abs(ux) < 1e-6 ? Infinity : box.halfWidth / Math.abs(ux)
  const ty = Math.abs(uy) < 1e-6 ? Infinity : (uy > 0 ? box.bottom : box.top) / Math.abs(uy)
  return Math.min(tx, ty)
}

/** Edge endpoints trimmed so lines stop at the shapes and their labels, leaving room for the arrowhead. */
function edgeGeometry(parent: Point, child: Point, parentBox: NodeBox, childBox: NodeBox) {
  const dx = child.x - parent.x
  const dy = child.y - parent.y
  const length = Math.hypot(dx, dy) || 1
  const ux = dx / length
  const uy = dy / length
  const start = Math.min(reach(parentBox, ux, uy), length / 2)
  const end = Math.min(reach(childBox, -ux, -uy) + 5, length / 2)
  return { x1: parent.x + ux * start, y1: parent.y + uy * start, x2: child.x - ux * end, y2: child.y - uy * end }
}

function nodeBox(node: GraphNode, labelLines: number): NodeBox {
  const radius = NODE_RADIUS[node.kind]
  if (node.kind === 'source') return { halfWidth: radius, top: radius, bottom: radius }
  return { halfWidth: Math.max(radius, 36), top: radius, bottom: radius + 6 + labelLines * 13 }
}

export const GraphCanvas = forwardRef<GraphCanvasHandle, Props>(function GraphCanvas(props, ref) {
  const { layout, index, nodes, edges, expanded, selectedId, viewRequest, handledRequest, viewStore, onSelect, onOpenFile, onToggleExpand, onTogglePin } = props
  const svgRef = useRef<SVGSVGElement>(null)
  const [view, setView] = useState<View>(() => viewStore.current ?? { x: 0, y: 0, k: 1 })
  // Whether a viewport was restored from the store at mount (checked before the store is overwritten).
  const restoredView = useRef(viewStore.current !== null)
  const viewRef = useRef(view)
  useLayoutEffect(() => { viewRef.current = view; viewStore.current = view }, [view, viewStore])
  const [, rerender] = useReducer((count: number) => count + 1, 0)
  const pointers = useRef(new Map<number, Point>())
  const drag = useRef<{ id: string; pointerId: number; start: Point; offset: Point; moved: boolean } | null>(null)
  const suppressClick = useRef(false)

  // Subscribe before syncing so that a synchronous layout (reduced motion, remount) re-renders with the new positions.
  useLayoutEffect(() => layout.subscribe(rerender), [layout])
  useLayoutEffect(() => { layout.sync(nodes, edges) }, [layout, nodes, edges])

  const size = useCallback(() => {
    const rect = svgRef.current?.getBoundingClientRect()
    return { width: rect?.width ?? 0, height: rect?.height ?? 0 }
  }, [])

  const toWorld = useCallback((clientX: number, clientY: number): Point => {
    const rect = svgRef.current!.getBoundingClientRect()
    const { x, y, k } = viewRef.current
    return { x: (clientX - rect.left - x) / k, y: (clientY - rect.top - y) / k }
  }, [])

  const zoomAt = useCallback((screen: Point, factor: number) => {
    setView(current => {
      const k = clampZoom(current.k * factor)
      const ratio = k / current.k
      return { k, x: screen.x - (screen.x - current.x) * ratio, y: screen.y - (screen.y - current.y) * ratio }
    })
  }, [])

  const fit = useCallback(() => {
    const { width, height } = size()
    const points = nodes.map(node => layout.node(node.id)).filter((node): node is NonNullable<typeof node> => node !== undefined)
    if (!width || !height || points.length === 0) return
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity
    for (const point of points) {
      minX = Math.min(minX, point.x - FIT_PADDING)
      maxX = Math.max(maxX, point.x + FIT_PADDING)
      minY = Math.min(minY, point.y - FIT_PADDING)
      maxY = Math.max(maxY, point.y + FIT_PADDING)
    }
    const k = clampZoom(Math.min(width / (maxX - minX), height / (maxY - minY), 1.25))
    const cx = (minX + maxX) / 2
    const cy = (minY + maxY) / 2
    setView({ k, x: width / 2 - cx * k, y: height / 2 - cy * k })
  }, [layout, nodes, size])

  const ensureVisible = useCallback((id: string) => {
    const node = layout.node(id)
    const { width, height } = size()
    if (!node || !width || !height) return
    setView(current => {
      const sx = node.x * current.k + current.x
      const sy = node.y * current.k + current.y
      const margin = 80
      if (sx > margin && sx < width - margin && sy > margin && sy < height - margin) return current
      return { ...current, x: width / 2 - node.x * current.k, y: height / 2 - node.y * current.k }
    })
  }, [layout, size])

  useImperativeHandle(ref, () => ({
    fit,
    zoomIn: () => { const { width, height } = size(); zoomAt({ x: width / 2, y: height / 2 }, 1.3) },
    zoomOut: () => { const { width, height } = size(); zoomAt({ x: width / 2, y: height / 2 }, 1 / 1.3) },
  }), [fit, size, zoomAt])

  // Fit once on first mount; a remount restores the stored viewport and afterwards only explicit requests move it.
  const mounted = useRef(false)
  useEffect(() => {
    if (mounted.current) return
    mounted.current = true
    if (!restoredView.current) fit()
  }, [fit])

  useEffect(() => {
    if (!viewRequest || viewRequest.token === handledRequest.current) return
    handledRequest.current = viewRequest.token
    if (viewRequest.type === 'fit') fit()
    else ensureVisible(viewRequest.id)
  }, [viewRequest, handledRequest, fit, ensureVisible])

  useEffect(() => {
    const svg = svgRef.current
    if (!svg) return
    const onWheel = (event: WheelEvent) => {
      event.preventDefault()
      const rect = svg.getBoundingClientRect()
      const factor = Math.exp(-event.deltaY * (event.deltaMode === 1 ? 0.05 : 0.0025))
      zoomAt({ x: event.clientX - rect.left, y: event.clientY - rect.top }, factor)
    }
    svg.addEventListener('wheel', onWheel, { passive: false })
    return () => svg.removeEventListener('wheel', onWheel)
  }, [zoomAt])

  // ---- Background panning and pinch zoom ----
  const onBackgroundPointerDown = (event: ReactPointerEvent<SVGElement>) => {
    if (event.button !== 0 && event.pointerType === 'mouse') return
    pointers.current.set(event.pointerId, { x: event.clientX, y: event.clientY })
    event.currentTarget.setPointerCapture(event.pointerId)
  }
  const onBackgroundPointerMove = (event: ReactPointerEvent<SVGElement>) => {
    const previous = pointers.current.get(event.pointerId)
    if (!previous) return
    const next = { x: event.clientX, y: event.clientY }
    if (pointers.current.size === 1) {
      setView(current => ({ ...current, x: current.x + next.x - previous.x, y: current.y + next.y - previous.y }))
    } else if (pointers.current.size === 2) {
      const [a, b] = [...pointers.current.entries()]
      const other = a[0] === event.pointerId ? b[1] : a[1]
      const rect = svgRef.current!.getBoundingClientRect()
      const oldDistance = Math.hypot(previous.x - other.x, previous.y - other.y) || 1
      const newDistance = Math.hypot(next.x - other.x, next.y - other.y) || 1
      const oldMid = { x: (previous.x + other.x) / 2 - rect.left, y: (previous.y + other.y) / 2 - rect.top }
      const newMid = { x: (next.x + other.x) / 2 - rect.left, y: (next.y + other.y) / 2 - rect.top }
      setView(current => {
        const k = clampZoom(current.k * (newDistance / oldDistance))
        const ratio = k / current.k
        return { k, x: newMid.x - (oldMid.x - current.x) * ratio, y: newMid.y - (oldMid.y - current.y) * ratio }
      })
    }
    pointers.current.set(event.pointerId, next)
  }
  const onBackgroundPointerEnd = (event: ReactPointerEvent<SVGElement>) => {
    pointers.current.delete(event.pointerId)
  }

  // ---- Node dragging ----
  const onNodePointerDown = (node: GraphNode) => (event: ReactPointerEvent<SVGGElement>) => {
    if (event.button !== 0 && event.pointerType === 'mouse') return
    const position = layout.node(node.id)
    if (!position) return
    const world = toWorld(event.clientX, event.clientY)
    drag.current = {
      id: node.id,
      pointerId: event.pointerId,
      start: { x: event.clientX, y: event.clientY },
      offset: { x: position.x - world.x, y: position.y - world.y },
      moved: false,
    }
    suppressClick.current = false
    event.currentTarget.setPointerCapture(event.pointerId)
    event.stopPropagation()
  }
  const onNodePointerMove = (event: ReactPointerEvent<SVGGElement>) => {
    const current = drag.current
    if (!current || current.pointerId !== event.pointerId) return
    if (!current.moved) {
      if (Math.hypot(event.clientX - current.start.x, event.clientY - current.start.y) < DRAG_THRESHOLD) return
      current.moved = true
      suppressClick.current = true
    }
    const world = toWorld(event.clientX, event.clientY)
    layout.drag(current.id, { x: world.x + current.offset.x, y: world.y + current.offset.y })
  }
  const onNodePointerEnd = (event: ReactPointerEvent<SVGGElement>) => {
    const current = drag.current
    if (!current || current.pointerId !== event.pointerId) return
    drag.current = null
    if (current.moved) layout.endDrag()
  }
  const activateNode = (node: GraphNode) => {
    if (node.kind === 'file') onOpenFile(node)
    else onSelect(node)
  }
  const onNodeClick = (node: GraphNode) => () => {
    // A drag that moved the node must never count as activation.
    if (suppressClick.current) { suppressClick.current = false; return }
    activateNode(node)
  }
  const onNodeKeyDown = (node: GraphNode) => (event: KeyboardEvent<SVGGElement>) => {
    const isFolder = node.kind !== 'file'
    switch (event.key) {
      case 'Enter':
      case ' ':
        activateNode(node)
        break
      case 'ArrowRight':
        if (isFolder && !expanded.has(node.id)) onToggleExpand(node)
        break
      case 'ArrowLeft':
        if (isFolder && expanded.has(node.id)) onToggleExpand(node)
        break
      case 'p':
      case 'P':
        onTogglePin(node)
        break
      default:
        return
    }
    event.preventDefault()
  }
  const stop = (event: ReactPointerEvent) => event.stopPropagation()
  const activate = (action: () => void) => (event: KeyboardEvent) => {
    if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); action() }
  }

  const showFileLabels = view.k >= 0.45
  const showFolderLabels = view.k >= 0.28
  const nodeById = new Map(nodes.map(node => [node.id, node]))
  const labelLines = (node: GraphNode) => {
    const shown = node.kind === 'source' || (node.kind === 'file' ? showFileLabels : showFolderLabels)
    return shown && node.kind !== 'source' ? wrapLabel(node.name).length : 0
  }

  return (
    <svg
      ref={svgRef}
      className="graph-canvas"
      role="group"
      aria-label="Directory graph"
      onPointerDown={onBackgroundPointerDown}
      onPointerMove={onBackgroundPointerMove}
      onPointerUp={onBackgroundPointerEnd}
      onPointerCancel={onBackgroundPointerEnd}
    >
      <defs>
        <marker id="contains-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
          <path d="M 1 1 L 9 5 L 1 9 z" className="edge-arrow" />
        </marker>
      </defs>
      <rect className="graph-background" width="100%" height="100%" />
      <g transform={`translate(${view.x} ${view.y}) scale(${view.k})`}>
        <g className="edges" aria-hidden="true">
          {edges.map(edge => {
            const parent = layout.node(edge.parentId)
            const child = layout.node(edge.childId)
            const parentNode = nodeById.get(edge.parentId)
            const childNode = nodeById.get(edge.childId)
            if (!parent || !child || !parentNode || !childNode) return null
            const highlighted = edge.parentId === selectedId || edge.childId === selectedId
            const geometry = edgeGeometry(parent, child, nodeBox(parentNode, labelLines(parentNode)), nodeBox(childNode, labelLines(childNode)))
            return (
              <line
                key={edge.id}
                className={highlighted ? 'edge edge-highlight' : 'edge'}
                data-edge-parent={edge.parentId}
                data-edge-child={edge.childId}
                {...geometry}
                markerEnd="url(#contains-arrow)"
              />
            )
          })}
        </g>
        <g className="nodes">
          {nodes.map(node => {
            const position = layout.node(node.id)
            if (!position) return null
            const radius = NODE_RADIUS[node.kind]
            const isFolder = node.kind !== 'file'
            const isExpanded = isFolder && expanded.has(node.id)
            const isSelected = node.id === selectedId
            const pinned = layout.isPinned(node.id)
            const counts = isFolder ? childCounts(index, node.id) : null
            const isEmpty = counts !== null && counts.directories + counts.files === 0
            const description = counts ? describeCounts(counts) : 'Markdown file'
            const label = isFolder
              ? `${node.name}, ${node.kind === 'source' ? 'source folder' : 'folder'}, ${description}${pinned ? ', pinned' : ''}`
              : `${node.name}, Markdown file${pinned ? ', pinned' : ''}`
            const showLabel = node.kind === 'source' || (node.kind === 'file' ? showFileLabels : showFolderLabels)
            const lines = node.kind === 'source' ? [node.name] : wrapLabel(node.name)
            const classes = ['node', `node-${node.kind}`, isSelected ? 'is-selected' : '', pinned ? 'is-pinned' : '']
            return (
              <g
                key={node.id}
                className={classes.join(' ').trim()}
                transform={`translate(${position.x} ${position.y})`}
                data-node-id={node.id}
                data-node-kind={node.kind}
                onFocus={event => {
                  // Pointer focus must not move the click/drag target before the gesture finishes.
                  if (event.target.matches(':focus-visible') && !event.target.hasAttribute('data-restoring-focus')) ensureVisible(node.id)
                }}
              >
                <g
                  className="node-body"
                  role="button"
                  tabIndex={0}
                  aria-label={label}
                  aria-pressed={isFolder ? isSelected : undefined}
                  onPointerDown={onNodePointerDown(node)}
                  onPointerMove={onNodePointerMove}
                  onPointerUp={onNodePointerEnd}
                  onPointerCancel={onNodePointerEnd}
                  onClick={onNodeClick(node)}
                  onKeyDown={onNodeKeyDown(node)}
                >
                  <title>{label}</title>
                  <circle className="focus-ring" r={radius + 6} />
                  {node.kind === 'source' && <circle className="shape" r={radius} />}
                  {node.kind === 'directory' && <path className="shape" d="M -20 -15 h 12 l 4 4 h 24 v 26 h -40 z" />}
                  {node.kind === 'file' && (
                    <>
                      <path className="shape" d="M -10 -14 h 14 l 6 6 v 22 h -20 z" />
                      <path className="shape-detail" d="M 4 -14 v 6 h 6 M -6 0 h 12 M -6 6 h 12" />
                    </>
                  )}
                  {showLabel && (
                    <text className="label" textAnchor="middle" y={node.kind === 'source' ? 5 : radius + 16} aria-hidden="true">
                      {lines.map((line, i) => <tspan key={i} x="0" dy={i === 0 ? 0 : 13}>{line}</tspan>)}
                    </text>
                  )}
                  {isExpanded && isEmpty && (
                    <text className="empty-tag" textAnchor="middle" y={radius + 16 + lines.length * 13} aria-hidden="true">empty</text>
                  )}
                </g>
                {isFolder && (
                  <g
                    className="node-toggle"
                    role="button"
                    tabIndex={0}
                    aria-expanded={isExpanded}
                    aria-label={`${isExpanded ? 'Collapse' : 'Expand'} ${node.name}`}
                    transform={`translate(${radius * 0.85} ${-radius * 0.85})`}
                    onPointerDown={stop}
                    onClick={() => onToggleExpand(node)}
                    onKeyDown={activate(() => onToggleExpand(node))}
                  >
                    <circle r={9} />
                    <path d={isExpanded ? 'M -4 0 h 8' : 'M -4 0 h 8 M 0 -4 v 8'} />
                  </g>
                )}
                {pinned && (
                  <g
                    className="node-pin"
                    role="button"
                    tabIndex={0}
                    aria-label={`Unpin ${node.name}`}
                    transform={`translate(${-radius * 0.85} ${-radius * 0.85})`}
                    onPointerDown={stop}
                    onClick={() => onTogglePin(node)}
                    onKeyDown={activate(() => onTogglePin(node))}
                  >
                    <circle r={8} />
                    <path d="M -3 -3 h 6 l -1 4 h -4 z M 0 1 v 5" />
                  </g>
                )}
              </g>
            )
          })}
        </g>
      </g>
    </svg>
  )
})

import { useState, type MouseEvent } from 'react'
import { breadcrumbsFor, breadcrumbsForFile, folderToPathname, type FileRef, type FolderRef } from './model.ts'

type Props = {
  selected: FolderRef | null
  /** When set, the trail leads to the file's folder and ends with the filename as a non-navigating item. */
  file?: FileRef | null
  onNavigate: (ref: FolderRef | null) => void
}

const MAX_VISIBLE = 4

/** Home / Source / folder … trail. Long trails collapse the middle behind an expandable “…” control. */
export function Breadcrumbs({ selected, file = null, onNavigate }: Props) {
  const [showAll, setShowAll] = useState(false)
  const crumbs = file ? breadcrumbsForFile(file) : breadcrumbsFor(selected)
  const collapsed = !showAll && crumbs.length > MAX_VISIBLE
  const hidden = collapsed ? crumbs.slice(1, crumbs.length - 2) : []
  const visible = collapsed ? [crumbs[0], ...crumbs.slice(crumbs.length - 2)] : crumbs

  const follow = (ref: FolderRef | null) => (event: MouseEvent<HTMLAnchorElement>) => {
    event.preventDefault()
    onNavigate(ref)
  }

  return (
    <nav className="breadcrumbs" aria-label="Breadcrumb">
      <ol>
        {visible.map((crumb, position) => {
          const isCurrent = position === visible.length - 1
          return (
            <li key={crumb.id}>
              {position === 1 && hidden.length > 0 && (
                <>
                  <button
                    type="button"
                    className="breadcrumb-ellipsis"
                    aria-expanded={false}
                    aria-label={`Show ${hidden.length} hidden breadcrumb ${hidden.length === 1 ? 'level' : 'levels'}`}
                    onClick={() => setShowAll(true)}
                  >
                    …
                  </button>
                  <span className="breadcrumb-separator" aria-hidden="true">/</span>
                </>
              )}
              {crumb.ref === undefined ? (
                <span className="breadcrumb-current" aria-current="page">{crumb.label}</span>
              ) : (
                <a href={folderToPathname(crumb.ref)} aria-current={isCurrent ? 'page' : undefined} onClick={follow(crumb.ref)}>
                  {crumb.label}
                </a>
              )}
              {!isCurrent && <span className="breadcrumb-separator" aria-hidden="true">/</span>}
            </li>
          )
        })}
      </ol>
    </nav>
  )
}

import {
  forceCollide,
  forceLink,
  forceManyBody,
  forceSimulation,
  forceX,
  forceY,
  type Simulation,
  type SimulationLinkDatum,
  type SimulationNodeDatum,
} from 'd3-force'
import type { GraphEdge, GraphNode, NodeKind, Source } from './model.ts'

export type Point = { x: number; y: number }

export type SimNode = SimulationNodeDatum & {
  id: string
  kind: NodeKind
  source: Source
  parentId: string | null
  x: number
  y: number
}

export type LayoutSnapshot = { nodes: SimNode[]; pinned: string[]; visibleIds: string[]; hasLaidOut: boolean }

type SimLink = SimulationLinkDatum<SimNode> & { source: SimNode; target: SimNode }

/** Drawn radius of each node type; also used to trim edges. */
export const NODE_RADIUS: Record<NodeKind, number> = { source: 30, directory: 20, file: 14 }
/** Personal space for collision avoidance, leaving room for the label below the shape. */
const COLLIDE_RADIUS: Record<NodeKind, number> = { source: 54, directory: 42, file: 34 }
const CHARGE: Record<NodeKind, number> = { source: -700, directory: -380, file: -160 }
/** Each source cluster is gently pulled to its own side so Pi and Claude stay recognisable. */
const SOURCE_ANCHOR: Record<Source, Point> = { Pi: { x: -180, y: 0 }, Claude: { x: 180, y: 0 } }
const ALPHA_MIN = 0.02
const MAX_SYNC_TICKS = 400

function linkDistance(link: SimLink): number {
  if (link.source.kind === 'source') return 130
  return link.target.kind === 'file' ? 80 : 105
}

/**
 * Owns the force simulation and every node position for the session. Positions of hidden nodes are
 * remembered so that expanding, collapsing and refreshing never rearranges unrelated parts of the graph.
 */
export class GraphLayout {
  private readonly nodes = new Map<string, SimNode>()
  private readonly pinned = new Set<string>()
  private readonly simulation: Simulation<SimNode, SimLink>
  private readonly listeners = new Set<() => void>()
  private visibleIds: string[] = []
  private hasLaidOut = false
  private synchronous: boolean

  constructor(options: { synchronous: boolean }) {
    this.synchronous = options.synchronous
    this.simulation = forceSimulation<SimNode>([])
      .stop()
      .alphaMin(ALPHA_MIN)
      .alphaDecay(0.05)
      .force('link', forceLink<SimNode, SimLink>([]).id(node => node.id).distance(linkDistance).strength(0.9))
      .force('charge', forceManyBody<SimNode>().strength(node => CHARGE[node.kind]).distanceMax(520))
      .force('collide', forceCollide<SimNode>().radius(node => COLLIDE_RADIUS[node.kind]).strength(0.9).iterations(2))
      .force('x', forceX<SimNode>(node => SOURCE_ANCHOR[node.source].x).strength(0.03))
      .force('y', forceY<SimNode>(node => SOURCE_ANCHOR[node.source].y).strength(0.03))
      .on('tick', () => this.notify())
      .on('end', () => this.notify())
  }

  /** Synchronous mode settles the layout instantly (reduced motion, tests) instead of animating ticks. */
  setSynchronous(value: boolean) {
    this.synchronous = value
  }

  subscribe(listener: () => void): () => void {
    this.listeners.add(listener)
    return () => { this.listeners.delete(listener) }
  }

  private notify() {
    for (const listener of this.listeners) listener()
  }

  node(id: string): SimNode | undefined {
    return this.nodes.get(id)
  }

  isPinned(id: string): boolean {
    return this.pinned.has(id)
  }

  /** Aligns the simulation with the currently visible nodes. New nodes appear beside their parent. */
  sync(visible: readonly GraphNode[], edges: readonly GraphEdge[]) {
    const previous = this.visibleIds
    const nextIds = visible.map(node => node.id)
    const unchanged = previous.length === nextIds.length && previous.every((id, i) => id === nextIds[i])
    if (unchanged && this.hasLaidOut) return
    const previouslyVisible = new Set(previous)
    const siblingCounter = new Map<string, number>()
    const simNodes: SimNode[] = []
    for (const node of visible) {
      let sim = this.nodes.get(node.id)
      if (!sim) {
        sim = { id: node.id, kind: node.kind, source: node.source, parentId: node.parentId, x: 0, y: 0 }
        this.nodes.set(node.id, sim)
        this.place(sim, siblingCounter)
      } else if (!previouslyVisible.has(node.id) && !this.pinned.has(node.id)) {
        this.place(sim, siblingCounter)
      }
      simNodes.push(sim)
    }
    const links: SimLink[] = []
    for (const edge of edges) {
      const source = this.nodes.get(edge.parentId)
      const target = this.nodes.get(edge.childId)
      if (source && target) links.push({ source, target })
    }
    this.visibleIds = nextIds
    this.simulation.nodes(simNodes)
    this.simulation.force<ReturnType<typeof forceLink<SimNode, SimLink>>>('link')!.links(links)
    // The very first layout has nothing to transition from, so it always settles instantly.
    this.run(this.hasLaidOut ? 0.6 : 1, !this.hasLaidOut)
    this.hasLaidOut = true
  }

  /** Deterministic placement: fan children out on the side of the parent facing away from the grandparent. */
  private place(sim: SimNode, siblingCounter: Map<string, number>) {
    if (sim.parentId === null) {
      const anchor = SOURCE_ANCHOR[sim.source]
      sim.x = anchor.x
      sim.y = anchor.y
      return
    }
    const parent = this.nodes.get(sim.parentId)
    if (!parent) return
    const index = siblingCounter.get(parent.id) ?? 0
    siblingCounter.set(parent.id, index + 1)
    const grandparent = parent.parentId ? this.nodes.get(parent.parentId) : undefined
    const base = grandparent ? Math.atan2(parent.y - grandparent.y, parent.x - grandparent.x) : -Math.PI / 2
    const angle = base + (index * 2.399963) // golden angle keeps siblings spread without randomness
    const distance = 60 + (index % 3) * 18
    sim.x = parent.x + Math.cos(angle) * distance
    sim.y = parent.y + Math.sin(angle) * distance
    sim.vx = 0
    sim.vy = 0
  }

  private run(alpha: number, forceSynchronous = false) {
    this.simulation.alpha(alpha)
    if (this.synchronous || forceSynchronous) {
      this.simulation.stop()
      for (let i = 0; i < MAX_SYNC_TICKS && this.simulation.alpha() > ALPHA_MIN; i += 1) this.simulation.tick()
      this.notify()
    } else {
      this.simulation.restart()
    }
  }

  /** Moves a node while it is being dragged. The node becomes pinned; the rest of the graph waits. */
  drag(id: string, point: Point) {
    const sim = this.nodes.get(id)
    if (!sim) return
    this.simulation.stop()
    sim.x = sim.fx = point.x
    sim.y = sim.fy = point.y
    sim.vx = 0
    sim.vy = 0
    this.pinned.add(id)
    this.notify()
  }

  /** After a drop, neighbours settle around the pinned node. */
  endDrag() {
    this.run(0.3)
  }

  pin(id: string) {
    const sim = this.nodes.get(id)
    if (!sim) return
    sim.fx = sim.x
    sim.fy = sim.y
    this.pinned.add(id)
    this.notify()
  }

  unpin(id: string) {
    const sim = this.nodes.get(id)
    if (!sim || !this.pinned.has(id)) return
    sim.fx = null
    sim.fy = null
    this.pinned.delete(id)
    this.run(0.3)
  }

  togglePin(id: string) {
    if (this.pinned.has(id)) this.unpin(id)
    else this.pin(id)
  }

  /** Forget nodes that no longer exist after a refresh. */
  prune(existing: ReadonlySet<string>) {
    for (const id of this.nodes.keys()) {
      if (!existing.has(id)) {
        this.nodes.delete(id)
        this.pinned.delete(id)
      }
    }
  }

  /** Copy values, never simulation objects: history entries must not share mutable positions. */
  snapshot(): LayoutSnapshot {
    return {
      nodes: [...this.nodes.values()].map(node => ({ ...node })),
      // prune() can run while the graph is unmounted, before sync() repairs visibility.
      pinned: [...this.pinned], visibleIds: this.visibleIds.filter(id => this.nodes.has(id)), hasLaidOut: this.hasLaidOut,
    }
  }

  restore(snapshot: LayoutSnapshot) {
    this.simulation.stop()
    this.simulation.force<ReturnType<typeof forceLink<SimNode, SimLink>>>('link')!.links([])
    this.nodes.clear()
    for (const node of snapshot.nodes) this.nodes.set(node.id, { ...node })
    this.pinned.clear()
    for (const id of snapshot.pinned) if (this.nodes.has(id)) this.pinned.add(id)
    this.visibleIds = snapshot.visibleIds.filter(id => this.nodes.has(id))
    this.hasLaidOut = snapshot.hasLaidOut
    const visible = this.visibleIds.map(id => this.nodes.get(id)!)
    this.simulation.nodes(visible)
    const ids = new Set(this.visibleIds)
    const links: SimLink[] = []
    for (const target of visible) {
      if (target.parentId && ids.has(target.parentId)) links.push({ source: this.nodes.get(target.parentId)!, target })
    }
    this.simulation.force<ReturnType<typeof forceLink<SimNode, SimLink>>>('link')!.links(links)
    this.notify()
  }

  /** Clears pins and remembered positions. */
  reset() {
    this.simulation.stop()
    this.nodes.clear()
    this.pinned.clear()
    this.visibleIds = []
    this.hasLaidOut = false
    this.notify()
  }

  dispose() {
    this.simulation.stop()
  }
}

