      assert.equal(await readFile(join(root, 'pi', 'new.md'), 'utf8'), '')

      const filled = await mutate(app, { op: 'create-file', source: 'Claude', path: 'nested/deeper/NOTE.MD', content: '# Hello\r\n' })
      assert.equal(filled.statusCode, 201, filled.body)
      assert.deepEqual(filled.json(), { op: 'create-file', source: 'Claude', path: 'nested/deeper/NOTE.MD' })
      assert.equal(await readFile(join(root, 'claude', 'nested', 'deeper', 'NOTE.MD'), 'utf8'), '# Hello\r\n')

