          mock.restoreAll()
          assert.equal((await mutate(app, payload)).statusCode, 201)
          assert.equal(await readFile(join(root, 'claude', 'new.md'), 'utf8'), 'complete content')
          assert.equal((await mutate(app, payload)).statusCode, 409)
          assert.equal(await readFile(join(root, 'claude', 'new.md'), 'utf8'), 'complete content')
