type CodeMirrorProps = {
  /** Initial draft; the parent remounts this editor on Revert/Reload with fresh serialization rules. */
  content: string
  analysis: TextAnalysis
  /** Fires with the serialized document (original line ending and BOM restored) after every change. */
  onChange: (content: string) => void
  onSave: () => void
  label: string
}

function CodeMirror({ content, analysis, onChange, onSave, label }: CodeMirrorProps) {
  const host = useRef<HTMLDivElement>(null)
  const latest = useRef({ onChange, onSave })
  useLayoutEffect(() => { latest.current = { onChange, onSave } })
  useEffect(() => {
    const extensions: Extension[] = [
      lineNumbers(), highlightSpecialChars(), history(), drawSelection(), highlightActiveLine(), bracketMatching(),
      markdown({ base: markdownLanguage }), syntaxHighlighting(markdownHighlight), editorTheme, EditorView.lineWrapping,
      EditorView.contentAttributes.of({ 'aria-label': label }),
      keymap.of([{ key: 'Mod-s', run: () => { latest.current.onSave(); return true } }, ...defaultKeymap, ...historyKeymap, indentWithTab]),
      EditorView.updateListener.of(update => {
        if (update.docChanged) latest.current.onChange(serializeText(update.state.doc, analysis))
      }),
    ]
    const view = new EditorView({ state: EditorState.create({ doc: textFromContent(content, analysis), extensions }), parent: host.current! })
    return () => view.destroy()
    // CodeMirror owns keystrokes until the parent remounts it with a new baseline/generation.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])
  return <div ref={host} className="editor-host" />
}

type Props = {
  fileRef: FileRef
  session: Session
  analysis: TextAnalysis
  onEdit: (content: string) => void
  onSave: () => void
  onRevert: () => void
  onReload: () => void
  onCopyDraft: () => void
  onExit: () => void
  /** Optional recovery panel shown by the parent (conflict/copy state). */
  recovery?: React.ReactNode
}

/** Editing shell: Edit/Preview tabs, Save/Revert/Done controls, accessible status and error guidance. */
export function Editor({ fileRef, session, analysis, onEdit, onSave, onRevert, onReload, onCopyDraft, onExit, recovery }: Props) {
  const [tab, setTab] = useState<Tab>('edit')
  const tabRefs = useRef<Array<HTMLButtonElement | null>>([])
  const current = status(session)
  const pending = isPending(session)
  const saveEnabled = analysis.editable && canSave(session)

  // Ctrl/Cmd+S anywhere in editing mode saves and never triggers the browser's Save Page.
  useEffect(() => {
    const onKeyDown = (event: globalThis.KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && !event.altKey && (event.key === 's' || event.key === 'S')) {
        event.preventDefault()
        if (saveEnabled) onSave()
      }
    }
    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
  }, [onSave, saveEnabled])

  // Warn on supported browser departures while there is unsaved or unacknowledged work.
  const dirty = hasUnacknowledgedWork(session)
  useEffect(() => {
    if (!dirty) return
    const warn = (event: BeforeUnloadEvent) => { event.preventDefault(); event.returnValue = '' }
    window.addEventListener('beforeunload', warn)
    return () => window.removeEventListener('beforeunload', warn)
  }, [dirty])

  const onTabKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    const index = TABS.findIndex(candidate => candidate.id === tab)
    let next: number | null = null
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown') next = (index + 1) % TABS.length
    else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') next = (index - 1 + TABS.length) % TABS.length
    else if (event.key === 'Home') next = 0
    else if (event.key === 'End') next = TABS.length - 1
    if (next === null) return
    event.preventDefault()
    setTab(TABS[next].id)
    tabRefs.current[next]?.focus()
  }

  const preview = useMemo(() => (tab === 'preview'
    ? session.draft === '' ? <p className="document-message">This draft is empty.</p> : <Markdown content={session.draft} />
    : null), [tab, session.draft])

  const error = session.error
  let guidance: React.ReactNode = null
  if (error) {
    const explanation = error.kind === 'conflict'
      ? 'This file changed on disk since it was last read. Your draft is kept but cannot be saved over the newer version. Reload to discard the draft and edit the current file, or copy the draft first.'
      : error.kind === 'too-large'
        ? `${error.message} Your draft is unchanged.`
        : error.kind === 'missing'
          ? 'The file no longer exists on disk, so the draft cannot be saved there. Copy the draft to keep it.'
          : `The save failed: ${error.message} Your draft, including edits made during the failed save, is unchanged. Retry with the last acknowledged version; if the earlier write did reach the disk, the retry reports a conflict instead of silently overwriting it.`
    guidance = (
      <div className="document-message document-error editor-error" role="alert">
        <p>{explanation}</p>
        <p className="document-actions">
          {error.kind === 'conflict' && <button type="button" className="button" onClick={onReload}>Reload</button>}
          {(error.kind === 'failed' || error.kind === 'too-large') && <button type="button" className="button" onClick={onSave}>Retry</button>}
          <button type="button" className="button" onClick={onCopyDraft}>Copy draft</button>
        </p>
      </div>
    )
  }

  return (
    <div className="editor" data-testid="editor" data-save-status={current}>
      <div className="editor-toolbar">
        <div className="tabs" role="tablist" aria-label="Editor">
          {TABS.map((candidate, index) => (
            <button
              key={candidate.id}
              ref={element => { tabRefs.current[index] = element }}
              type="button"
              role="tab"
              id={`editor-tab-${candidate.id}`}
              className="tab"
              aria-selected={tab === candidate.id}
              aria-controls="editor-panel"
              tabIndex={tab === candidate.id ? 0 : -1}
              onClick={() => setTab(candidate.id)}
              onKeyDown={onTabKeyDown}
            >
              {candidate.label}
            </button>
          ))}
        </div>
        <div className="editor-actions">
          <span className={`save-status save-status-${current}`} data-testid="save-status" aria-live="polite" aria-atomic="true">
            {STATUS_LABEL[current]}
          </span>
          <button type="button" className="button" onClick={onSave} disabled={!saveEnabled} aria-keyshortcuts="Control+S Meta+S">Save</button>
          <button type="button" className="button" onClick={onRevert} disabled={!analysis.editable || !canRevert(session)}>Revert</button>
          <button type="button" className="button" onClick={onExit} disabled={pending} title={pending ? 'Wait for the save to finish.' : undefined}>Done</button>
        </div>
      </div>
      {!analysis.editable && <p className="document-notice">This file is read-only here because {analysis.reason}. <button type="button" className="button" onClick={onReload}>Reload</button></p>}
      {guidance}
      {recovery}
      <div className="editor-panel" role="tabpanel" id="editor-panel" aria-labelledby={`editor-tab-${tab}`}>
        <div hidden={tab !== 'edit'}>
          {analysis.editable
            ? <CodeMirror key={session.generation} content={session.draft} analysis={analysis} onChange={onEdit} onSave={onSave} label={`Editing ${fileRef.path}`} />
            : <pre className="document-source" tabIndex={0}>{session.draft}</pre>}
        </div>
        {preview}
      </div>
    </div>
  )
}
/**
 * Pure explicit-save state machine for one editing session of one document. No React, no network.
 *
 * - `baseline` is captured once when Edit begins and never changes until a Reload.
 * - `acknowledged` is the last content/hash the server confirmed (read or successful write).
 * - `draft` is what the editor holds now. Keystrokes only change `draft`.
 * - At most one request is `inFlight`; explicit saves while one is pending fill a single `queued` slot.
 * - A failure or conflict empties the queue; a conflict blocks Save and Revert until `reloaded`.
 */
export type Snapshot = { content: string; hash: string }
export type SaveErrorKind = 'failed' | 'conflict' | 'too-large' | 'missing'
export type SaveError = { kind: SaveErrorKind; message: string }
export type Request = { token: number; content: string; expectedHash: string; purpose: 'save' | 'revert' }
export type Session = {
  readonly baseline: Snapshot
  readonly acknowledged: Snapshot
  readonly draft: string
  readonly inFlight: Request | null
  readonly queued: { content: string } | null
  readonly error: SaveError | null
  readonly conflicted: boolean
  readonly nextToken: number
  /** Increments whenever the draft is replaced from outside the editor (Revert success, Reload). */
  readonly generation: number
}
export type SaveStatus = 'saved' | 'unsaved' | 'saving' | 'error'

export function startSession(document: Snapshot): Session {
  const snapshot = { content: document.content, hash: document.hash }
  return { baseline: snapshot, acknowledged: snapshot, draft: document.content, inFlight: null, queued: null, error: null, conflicted: false, nextToken: 1, generation: 0 }
}

export function edit(session: Session, draft: string): Session {
  return draft === session.draft ? session : { ...session, draft }
}

function send(session: Session, content: string, purpose: Request['purpose']): Session {
  const request: Request = { token: session.nextToken, content, expectedHash: session.acknowledged.hash, purpose }
  return { ...session, inFlight: request, queued: null, error: null, nextToken: session.nextToken + 1 }
}

/** Explicit Save (button, shortcut or Retry). Never sends concurrently; never sends an unchanged draft. */
export function requestSave(session: Session): Session {
  if (session.conflicted) return session
  if (session.inFlight) {
    if (session.draft === session.inFlight.content) return session.queued ? { ...session, queued: null } : session
    return { ...session, queued: { content: session.draft } }
  }
  if (session.draft === session.acknowledged.content) return session.error ? { ...session, error: null } : session
  return send(session, session.draft, 'save')
}

/** Revert restores the Edit baseline on disk through the same hash-checked pipeline. */
export function requestRevert(session: Session): Session {
  if (!canRevert(session)) return session
  return send(session, session.baseline.content, 'revert')
}

export function settleSuccess(session: Session, token: number, hash: string): Session {
  const request = session.inFlight
  if (!request || request.token !== token) return session
  const acknowledged = { content: request.content, hash }
  const reverted = request.purpose === 'revert'
  const draft = reverted ? request.content : session.draft
  const settled: Session = { ...session, acknowledged, draft, inFlight: null, error: null, conflicted: false, generation: session.generation + (reverted ? 1 : 0) }
  if (session.queued && session.queued.content !== acknowledged.content) return send(settled, session.queued.content, 'save')
  return { ...settled, queued: null }
}

export function settleFailure(session: Session, token: number, error: SaveError): Session {
  const request = session.inFlight
  if (!request || request.token !== token) return session
  return { ...session, inFlight: null, queued: null, error, conflicted: error.kind === 'conflict' }
}

/** A successful fresh read replaces baseline, acknowledged content and draft, and clears any conflict. */
export function reloaded(session: Session, document: Snapshot): Session {
  if (session.inFlight) return session
  return { ...startSession(document), nextToken: session.nextToken, generation: session.generation + 1 }
}

export function status(session: Session): SaveStatus {
  if (session.inFlight) return 'saving'
  if (session.error) return 'error'
  return session.draft === session.acknowledged.content ? 'saved' : 'unsaved'
}

export function canSave(session: Session): boolean {
  return !session.conflicted
}

export function canRevert(session: Session): boolean {
  if (session.conflicted || session.inFlight || session.queued) return false
  return session.draft !== session.baseline.content || session.acknowledged.content !== session.baseline.content
}

/** Unsaved changes or a save that has not been acknowledged: what navigation guards and beforeunload care about. */
export function hasUnacknowledgedWork(session: Session): boolean {
  return session.inFlight !== null || session.queued !== null || session.draft !== session.acknowledged.content
}

export function isPending(session: Session): boolean {
  return session.inFlight !== null || session.queued !== null
}
import { useCallback, useEffect, useRef, useState } from 'react'
import type { FileRef } from '../graph/model.ts'
import { SaveError, saveDocument } from './api.ts'
import {
  edit as editDraft,
  reloaded as reloadSession,
  requestRevert as revertRequest,
  requestSave as saveRequest,
  settleFailure,
  settleSuccess,
  startSession,
  type Session,
  type Snapshot,
} from './editSession.ts'

type Events = {
  onSaved?: (purpose: 'save' | 'revert') => void
