      assert.equal(noDestination.statusCode, 400)
      const folder = await mutate(app, { op: 'copy', source: 'Pi', path: 'skills', destinationSource: 'Claude', destinationPath: 'skills' })
      assert.equal(folder.statusCode, 404)
      const missingParent = await mutate(app, { op: 'copy', source: 'Pi', path: 'skills/review.md', destinationSource: 'Claude', destinationPath: 'nope/review.md' })
      assert.equal(missingParent.statusCode, 404)
      const extension = await mutate(app, { op: 'copy', source: 'Pi', path: 'skills/review.md', destinationSource: 'Claude', destinationPath: 'imported/review.txt' })
